  // 文字数カウンター
  function setupCharacterCounter(textareaId, counterId, maxLength) {
    const textarea = container.querySelector(`#${textareaId}`);
    const counter = container.querySelector(`#${counterId}`);

    textarea.addEventListener("input", () => {
      const currentLength = textarea.value.length;
      counter.textContent = currentLength;

      if (currentLength > maxLength) {
        counter.style.color = "#ff6a00";
      } else {
        counter.style.color = "var(--text-muted)";
      }
    });
  }

  // 異常報告チェックボックスの制御
  function setupIssueReportToggle() {
    const hasIssueCheckbox = container.querySelector("#has-issue");
    const issueContentSection = container.querySelector("#issue-content-section");
    const issueContentTextarea = container.querySelector("#issue-content");

    hasIssueCheckbox.addEventListener("change", () => {
      if (hasIssueCheckbox.checked) {
        issueContentSection.style.display = "block";
      } else {
        issueContentSection.style.display = "none";
        issueContentTextarea.value = "";
        container.querySelector("#issue-count").textContent = "0";
      }
