    const hasIssue = container.querySelector("#has-issue").checked;
    const issueContent = container.querySelector("#issue-content").value.trim();
    const workMemo = container.querySelector("#work-memo").value;
    const issueContentValue = container.querySelector("#issue-content").value;

    // 完了状況必須チェック
    if (!completionStatus) {
      showError("完了状況を選択してください。");
      return false;
    }

    // 異常報告チェック時の異常内容必須チェック
    if (hasIssue && !issueContent) {
      showError("異常内容を入力してください。");
      return false;
    }

    // 作業メモ文字数チェック
    if (workMemo.length > 1000) {
      showError("作業メモは1000文字以内で入力してください。");
      return false;
    }

    // 異常内容文字数チェック
    if (issueContentValue.length > 500) {
