    });
    cancelBtn.addEventListener("mouseleave", () => {
      cancelBtn.style.background = "transparent";
    });

    checkRecordBtn.addEventListener("mouseenter", () => {
      checkRecordBtn.style.background = "rgba(255,255,255,0.05)";
    });
    checkRecordBtn.addEventListener("mouseleave", () => {
      checkRecordBtn.style.background = "transparent";
    });
  }

  // 初期化
  displayTimeInfo();
  setupCharacterCounter("work-memo", "memo-count", 1000);
  setupCharacterCounter("issue-content", "issue-count", 500);
  setupIssueReportToggle();
  setupEventListeners();
}

function(container, apiUrl, tables) {
  let autoSaveInterval = null;
  let currentSaveInterval = 30; // デフォルト30秒
  let localData = JSON.parse(localStorage.getItem('workRecordsLocal') || '[]');
  let isOnline = navigator.onLine;
  let retryCount = 0;
  const maxRetries = 3;

  // ローカルデータ再描画関数
  function renderLocalData() {
    const tbody = container.querySelector('#local-data-tbody');
    if (localData.length === 0) {
      tbody.innerHTML = `
        <tr>
          <td colspan="4" style="padding: 20px; text-align: center; color: var(--text-muted); font-size: 12px;">
            ローカル保存データはありません
          </td>
        </tr>
      `;
    } else {
      tbody.innerHTML = localData.map(item => `
        <tr data-id="${item.id}">
          <td style="padding: 6px 10px; font-size: 12px; color: var(--text);">${new Date(item.作業日).toLocaleString()}</td>
          <td style="padding: 6px 10px; font-size: 12px; color: var(--text);">${(item.作業内容 || '').substring(0, 30)}${(item.作業内容 || '').length > 30 ? '...' : ''}</td>
          <td style="padding: 6px 10px; font-size: 12px;">
            <span style="background: ${item.synced ? 'rgba(106,255,106,0.2)' : 'rgba(255,165,0,0.2)'}; color: ${item.synced ? '#6aff6a' : '#ffa500'}; padding: 2px 6px; border-radius: 4px; font-size: 11px;">
              ${item.synced ? '同期済み' : '未同期'}
            </span>
          </td>
          <td style="padding: 6px 10px;">
            <button class="delete-local-btn" data-id="${item.id}" style="background: transparent; color: #ff6a6a; border: 1px solid #ff6a6a; padding: 2px 6px; border-radius: 4px; font-size: 11px; cursor: pointer;">削除</button>
          </td>
        </tr>
      `).join('');
    }
    updatePendingSyncCount();
  }

  // 同期待ち件数更新
  function updatePendingSyncCount() {
    const pendingCount = localData.filter(item => !item.synced).length;
    container.querySelector('#pending-sync-count').textContent = `${pendingCount}件`;

    // 上限チェック（100件）
    if (pendingCount >= 100) {
      showError('同期待ちデータが上限（100件）に達しています。手動同期を実行してください。');
    }
  }

  // ネットワーク状態更新
  function updateNetworkStatus() {
    const statusEl = container.querySelector('#network-status');
    statusEl.textContent = isOnline ? 'オンライン' : 'オフライン';
    statusEl.style.color = isOnline ? '#6aff6a' : '#ff6a6a';
  }

  // エラー表示
  function showError(message) {
    const errorEl = container.querySelector('#error-notification');
    const messageEl = container.querySelector('#error-message');
    messageEl.textContent = message;
    errorEl.style.display = 'block';
  }

  // エラー非表示
  function hideError() {
    container.querySelector('#error-notification').style.display = 'none';
  }

  // 最終保存時刻更新
  function updateLastSaveTime() {
    const now = new Date();
    container.querySelector('#last-save-time').textContent = 
      `${now.getHours().toString().padStart(2, '0')}:${now.getMinutes().toString().padStart(2, '0')}`;
  }

  // 自動保存処理
  function startAutoSave() {
    if (autoSaveInterval) {
      clearInterval(autoSaveInterval);
    }

    autoSaveInterval = setInterval(async () => {
      try {
        // 未同期データがある場合は同期を試行
        const pendingData = localData.filter(item => !item.synced);
        if (pendingData.length > 0 && isOnline) {
          await syncPendingData();
        }
        updateLastSaveTime();
      } catch (error) {
        console.error('Auto save error:', error);
        showError('自動保存中にエラーが発生しました: ' + error.message);
      }
    }, currentSaveInterval * 1000);
  }

  // 未同期データの同期
  async function syncPendingData() {
    const pendingData = localData.filter(item => !item.synced);
    let syncedCount = 0;

    for (const item of pendingData) {
      try {
        // ストレージ容量チェック
        if (localStorage.length > 5000000) { // 約5MB
          throw new Error('ストレージ容量不足');
        }

        const result = await window.aivicApi.save(1, {
          作業員ID: item.作業員ID,
          作業日: item.作業日,
          作業開始時刻: item.作業開始時刻,
          作業終了時刻: item.作業終了時刻,
          作業時間: item.作業時間,
          プロジェクト名: item.プロジェクト名,
          作業場所: item.作業場所,
          作業種別: item.作業種別,
          作業内容: item.作業内容,
          進捗状況: item.進捗状況,
          備考: item.備考,
          承認状態: '未承認',
          作成者ID: item.作業員ID
        });

        if (result) {
          // 同期成功
          const index = localData.findIndex(d => d.id === item.id);
          if (index !== -1) {
            localData[index].synced = true;
            syncedCount++;
          }
        }
      } catch (error) {
        console.error('Sync error for item:', item.id, error);
        if (error.message.includes('容量不足')) {
          showError('保存に失敗しました。端末の容量不足が原因の可能性があります。不要なファイルを削除してから再度お試しください。');
        } else {
          showError('データの同期に失敗しました: ' + error.message);
        }
        break;
      }
    }

    if (syncedCount > 0) {
      localStorage.setItem('workRecordsLocal', JSON.stringify(localData));
      renderLocalData();
      hideError();
      retryCount = 0; // 成功時はリトライカウントをリセット
    }

    return syncedCount;
  }

  // 手動同期
  async function manualSync() {
    if (!isOnline) {
      showError('オフライン状態のため同期できません。ネットワーク接続を確認してください。');
      return;
    }

    const btn = container.querySelector('#btn-manual-sync');
    btn.disabled = true;
    btn.textContent = '同期中...';

    try {
      const syncedCount = await syncPendingData();
      if (syncedCount > 0) {
        alert(`${syncedCount}件のデータを同期しました。`);
      } else {
        alert('同期対象のデータがありません。');
      }
    } catch (error) {
      showError('手動同期に失敗しました: ' + error.message);
    } finally {
      btn.disabled = false;
      btn.textContent = '手動同期実行';
    }
  }

  // データ復旧
  function dataRecovery() {
    const unsavedData = JSON.parse(localStorage.getItem('unsavedWorkData') || 'null');
    if (unsavedData) {
      if (confirm('未保存のデータが見つかりました。復旧しますか？')) {
        // 復旧処理
        localData.push({
          id: Date.now().toString(),
          ...unsavedData,
          synced: false
        });
        localStorage.setItem('workRecordsLocal', JSON.stringify(localData));
        localStorage.removeItem('unsavedWorkData');
        renderLocalData();
        alert('データを復旧しました。');
      }
    } else {
      alert('復旧可能なデータが見つかりません。');
    }
  }

  // 初期化
  renderLocalData();
  updateNetworkStatus();
  updateLastSaveTime();
  startAutoSave();

  // 保存間隔設定
  container.querySelector('#save-interval').value = currentSaveInterval;

  // イベントリスナー
  container.querySelector('#btn-save-settings').addEventListener('click', () => {
    const interval = parseInt(container.querySelector('#save-interval').value);
    const errorEl = container.querySelector('#settings-error');

    if (interval < 1) {
      errorEl.textContent = '保存間隔は1秒以上で設定してください';
      errorEl.style.display = 'block';
      return;
    }

    if (interval > 86400) {
      errorEl.textContent = '保存間隔は86400秒以下で設定してください';
      errorEl.style.display = 'block';
      return;
    }

    currentSaveInterval = interval;
    localStorage.setItem('autoSaveInterval', interval.toString());
    startAutoSave();
    errorEl.style.display = 'none';
    alert('保存間隔を更新しました。');
  });

  container.querySelector('#btn-manual-sync').addEventListener('click', manualSync);
  container.querySelector('#btn-data-recovery').addEventListener('click', dataRecovery);

  container.querySelector('#btn-retry').addEventListener('click', async () => {
    hideError();
    if (retryCount < maxRetries) {
      retryCount++;
      try {
        await syncPendingData();
      } catch (error) {
        showError(`再試行に失敗しました (${retryCount}/${maxRetries}): ` + error.message);
      }
    } else {
      showError('最大再試行回数に達しました。しばらく時間をおいてから手動同期をお試しください。');
    }
  });

  container.querySelector('#btn-clear-local').addEventListener('click', () => {
    if (confirm('ローカル保存データをすべて削除しますか？未同期のデータも削除されます。')) {
      localData = [];
      localStorage.setItem('workRecordsLocal', JSON.stringify(localData));
      renderLocalData();
    }
  });

  // ローカルデータ削除
  container.addEventListener('click', (e) => {
    const deleteBtn = e.target.closest('.delete-local-btn');
    if (deleteBtn) {
      const id = deleteBtn.dataset.id;
      if (confirm('このデータを削除しますか？')) {
        localData = localData.filter(item => item.id !== id);
        localStorage.setItem('workRecordsLocal', JSON.stringify(localData));
        renderLocalData();
      }
    }
  });

  // ネットワーク状態監視
  window.addEventListener('online', () => {
    isOnline = true;
    updateNetworkStatus();
    hideError();
    // オンライン復旧時の自動同期
    setTimeout(async () => {
      try {
        await syncPendingData();
      } catch (error) {
        showError('自動同期に失敗しました: ' + error.message);
      }
    }, 1000);
  });

  window.addEventListener('offline', () => {
    isOnline = false;
    updateNetworkStatus();
  });

  // 保存間隔の復元
  const savedInterval = localStorage.getItem('autoSaveInterval');
  if (savedInterval) {
    currentSaveInterval = parseInt(savedInterval);
    container.querySelector('#save-interval').value = currentSaveInterval;
    startAutoSave();
  }

  // ページ離脱時の未保存データ保護
  window.addEventListener('beforeunload', () => {
    // 現在編集中のデータがあれば保存
    const currentForm = document.querySelector('form');
    if (currentForm) {
      const formData = new FormData(currentForm);
      const data = Object.fromEntries(formData.entries());
      if (Object.values(data).some(value => value.trim())) {
        localStorage.setItem('unsavedWorkData', JSON.stringify(data));
      }
    }
  });
}

function(container, apiUrl, tables) {
  let currentRecords = [];
  let deleteTargetId = null;

  // 時間フォーマット関数
  function formatTime(timestamp) {
    if (!timestamp) return '-';
    const date = new Date(timestamp);
    return date.toLocaleTimeString('ja-JP', { hour: '2-digit', minute: '2-digit' });
  }

  // 日付フォーマット関数
  function formatDate(timestamp) {
    if (!timestamp) return '-';
    const date = new Date(timestamp);
    return date.toLocaleDateString('ja-JP');
  }

  // 作業時間計算関数（分単位を時間:分に変換）
  function formatWorkTime(minutes) {
    if (!minutes || minutes === 0) return '-';
    const hours = Math.floor(minutes / 60);
    const mins = minutes % 60;
    return `${hours}時間${mins}分`;
  }

  // 異常値チェック関数
  function checkAbnormalValue(record) {
    const warnings = [];

    // 24時間を超える作業時間
    if (record.作業時間 && record.作業時間 > 1440) { // 1440分 = 24時間
      warnings.push('24時間超過');
    }

    // 終了時刻が開始時刻より早い
    if (record.作業開始時刻 && record.作業終了時刻) {
      const start = new Date(record.作業開始時刻);
      const end = new Date(record.作業終了時刻);
      if (end < start) {
        warnings.push('時刻異常');
      }
    }

    return warnings;
  }

  // 中断時間計算関数
  function calculateBreakTime(recordId) {
    const breakRecords = tables[2]?.records?.filter(br => br.作業記録ID === recordId) || [];
    return breakRecords.reduce((total, br) => total + (br.中断時間 || 0), 0);
  }

  // 権限チェック関数
  function canEdit(record) {
    return record.承認状態 !== '承認済み';
  }

  function canDelete(record) {
    return record.承認状態 !== '承認済み';
  }

  // テーブル再描画関数
  function renderRows(rows) {
    const tbody = container.querySelector('#records-tbody');
    const emptyMessage = container.querySelector('#empty-message');

    if (!rows || rows.length === 0) {
      tbody.innerHTML = '';
      emptyMessage.classList.remove('hidden');
      return;
    }

    emptyMessage.classList.add('hidden');

    tbody.innerHTML = rows.map(record => {
      const warnings = checkAbnormalValue(record);
      const breakTime = calculateBreakTime(record.作業記録ID);
      const warningIcon = warnings.length > 0 ? `<span style="color: #ff6a00; margin-left: 4px;" title="${warnings.join(', ')}">⚠️</span>` : '';

      return `
        <tr data-id="${record.作業記録ID}" style="border-bottom: 1px solid rgba(255,255,255,0.02);">
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${formatDate(record.作業日)}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${formatTime(record.作業開始時刻)}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${formatTime(record.作業終了時刻)}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${formatWorkTime(record.作業時間)}${warningIcon}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${formatWorkTime(breakTime)}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text); max-width: 200px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;">${record.作業内容 || '-'}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${record.作業場所 || '-'}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">
            <span style="padding: 2px 6px; border-radius: 4px; font-size: 11px; background: ${record.承認状態 === '承認済み' ? 'rgba(40,167,69,0.2)' : record.承認状態 === '差し戻し' ? 'rgba(220,53,69,0.2)' : 'rgba(255,193,7,0.2)'}; color: ${record.承認状態 === '承認済み' ? '#28a745' : record.承認状態 === '差し戻し' ? '#dc3545' : '#ffc107'};">
              ${record.承認状態}
            </span>
          </td>
          <td style="padding: 6px 10px; text-align: center;">
            <div style="display: flex; gap: 4px; justify-content: center;">
              <button class="detail-btn" data-id="${record.作業記録ID}" style="background: var(--primary); color: #fff; border: none; padding: 4px 8px; border-radius: 4px; font-size: 11px; cursor: pointer;">詳細</button>
              ${canEdit(record) ? `<button class="edit-btn" data-id="${record.作業記録ID}" style="background: transparent; color: var(--text); border: 1px solid rgba(255,255,255,0.18); padding: 4px 8px; border-radius: 4px; font-size: 11px; cursor: pointer;">修正</button>` : ''}
              ${canDelete(record) ? `<button class="delete-btn" data-id="${record.作業記録ID}" style="background: #dc3545; color: #fff; border: none; padding: 4px 8px; border-radius: 4px; font-size: 11px; cursor: pointer;">削除</button>` : ''}
            </div>
          </td>
        </tr>
      `;
    }).join('');
  }

  // 詳細表示関数
  function showDetail(recordId) {
    const record = currentRecords.find(r => r.作業記録ID === recordId);
    if (!record) return;

    const breakRecords = tables[2]?.records?.filter(br => br.作業記録ID === recordId) || [];
    const breakTime = calculateBreakTime(recordId);
    const warnings = checkAbnormalValue(record);

    const detailContent = container.querySelector('#detail-content');
    detailContent.innerHTML = `
      <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 12px; margin-bottom: 16px;">
        <div>
          <label style="font-size: 11px; color: var(--text-muted); margin-bottom: 4px; display: block;">作業日</label>
          <div style="font-size: 13px; color: var(--text);">${formatDate(record.作業日)}</div>
        </div>
        <div>
          <label style="font-size: 11px; color: var(--text-muted); margin-bottom: 4px; display: block;">プロジェクト名</label>
          <div style="font-size: 13px; color: var(--text);">${record.プロジェクト名 || '-'}</div>
        </div>
        <div>
          <label style="font-size: 11px; color: var(--text-muted); margin-bottom: 4px; display: block;">開始時刻</label>
          <div style="font-size: 13px; color: var(--text);">${formatTime(record.作業開始時刻)}</div>
        </div>
        <div>
          <label style="font-size: 11px; color: var(--text-muted); margin-bottom: 4px; display: block;">終了時刻</label>
          <div style="font-size: 13px; color: var(--text);">${formatTime(record.作業終了時刻)}</div>
        </div>
        <div>
          <label style="font-size: 11px; color: var(--text-muted); margin-bottom: 4px; display: block;">作業時間</label>
          <div style="font-size: 13px; color: var(--text);">${formatWorkTime(record.作業時間)}</div>
        </div>
        <div>
          <label style="font-size: 11px; color: var(--text-muted); margin-bottom: 4px; display: block;">中断時間</label>
          <div style="font-size: 13px; color: var(--text);">${formatWorkTime(breakTime)}</div>
        </div>
        <div>
          <label style="font-size: 11px; color: var(--text-muted); margin-bottom: 4px; display: block;">作業場所</label>
          <div style="font-size: 13px; color: var(--text);">${record.作業場所 || '-'}</div>
        </div>
        <div>
          <label style="font-size: 11px; color: var(--text-muted); margin-bottom: 4px; display: block;">作業種別</label>
          <div style="font-size: 13px; color: var(--text);">${record.作業種別 || '-'}</div>
        </div>
      </div>
      <div style="margin-bottom: 16px;">
        <label style="font-size: 11px; color: var(--text-muted); margin-bottom: 4px; display: block;">作業内容</label>
        <div style="font-size: 13px; color: var(--text); padding: 8px; background: rgba(0,0,0,0.25); border-radius: 6px; min-height: 60px;">${record.作業内容 || '-'}</div>
      </div>
      ${record.備考 ? `
      <div style="margin-bottom: 16px;">
        <label style="font-size: 11px; color: var(--text-muted); margin-bottom: 4px; display: block;">備考</label>
        <div style="font-size: 13px; color: var(--text); padding: 8px; background: rgba(0,0,0,0.25); border-radius: 6px;">${record.備考}</div>
      </div>
      ` : ''}
      ${warnings.length > 0 ? `
      <div style="margin-bottom: 16px;">
        <label style="font-size: 11px; color: var(--text-muted); margin-bottom: 4px; display: block;">警告</label>
        <div style="font-size: 13px; color: #ff6a00; padding: 8px; background: rgba(255,106,0,0.1); border-radius: 6px; border-left: 3px solid #ff6a00;">
          ${warnings.join(', ')}
        </div>
      </div>
      ` : ''}
      ${breakRecords.length > 0 ? `
      <div>
        <label style="font-size: 11px; color: var(--text-muted); margin-bottom: 8px; display: block;">中断記録</label>
        <div style="background: rgba(0,0,0,0.25); border-radius: 6px; padding: 8px;">
          ${breakRecords.map(br => `
            <div style="margin-bottom: 8px; padding: 6px; background: rgba(255,255,255,0.02); border-radius: 4px;">
              <div style="font-size: 12px; color: var(--text); margin-bottom: 2px;">
                ${formatTime(br.中断開始日時)} - ${formatTime(br.中断終了日時)} (${formatWorkTime(br.中断時間)})
              </div>
              <div style="font-size: 11px; color: var(--text-muted);">理由: ${br.中断理由区分} ${br.中断理由詳細 ? '- ' + br.中断理由詳細 : ''}</div>
            </div>
          `).join('')}
        </div>
      </div>
      ` : ''}
    `;

    container.querySelector('#detail-modal').classList.remove('hidden');
  }

  // CSVエクスポート関数
  function exportCSV() {
    if (!currentRecords || currentRecords.length === 0) {
      alert('エクスポートするデータがありません');
      return;
    }

    const headers = ['作業日', '開始時刻', '終了時刻', '作業時間', '中断時間', 'プロジェクト名', '作業場所', '作業種別', '作業内容', '進捗状況', '承認状態', '備考'];

    const csvData = currentRecords.map(record => {
      const breakTime = calculateBreakTime(record.作業記録ID);
      return [
        formatDate(record.作業日),
        formatTime(record.作業開始時刻),
        formatTime(record.作業終了時刻),
        formatWorkTime(record.作業時間),
        formatWorkTime(breakTime),
        record.プロジェクト名 || '',
        record.作業場所 || '',
        record.作業種別 || '',
        (record.作業内容 || '').replace(/"/g, '""'),
        record.進捗状況 || '',
        record.承認状態 || '',
        (record.備考 || '').replace(/"/g, '""')
      ].map(field => `"${field}"`).join(',');
    });

    const csv = '\uFEFF' + [headers.join(','), ...csvData].join('\n');
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `work_records_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // 初期データ読み込み
  window.aivicApi.list(1).then(rows => {
    currentRecords = rows || [];
    renderRows(currentRecords);
  });

  // 今日の日付を設定
  const today = new Date().toISOString().split('T')[0];
  container.querySelector('#date-filter').value = today;

  // 絞り込みボタンイベント
  container.querySelector('#btn-filter').addEventListener('click', async () => {
    const dateFilter = container.querySelector('#date-filter').value;
    const startDate = container.querySelector('#start-date').value;
    const endDate = container.querySelector('#end-date').value;

    // 日付範囲チェック
    if (startDate && endDate && startDate > endDate) {
      alert('開始日は終了日より前の日付を指定してください');
      return;
    }

    const rows = await window.aivicApi.list(1);
    let filteredRows = rows || [];

    if (dateFilter) {
      filteredRows = filteredRows.filter(record => {
        const recordDate = new Date(record.作業日).toISOString().split('T')[0];
        return recordDate === dateFilter;
      });
    } else if (startDate || endDate) {
      filteredRows = filteredRows.filter(record => {
        const recordDate = new Date(record.作業日).toISOString().split('T')[0];
        if (startDate && recordDate < startDate) return false;
        if (endDate && recordDate > endDate) return false;
        return true;
      });
    }

    currentRecords = filteredRows;
    renderRows(currentRecords);
  });

  // CSVエクスポートボタンイベント
  container.querySelector('#btn-csv-export').addEventListener('click', exportCSV);

  // メニューに戻るボタンイベント
  container.querySelector('#btn-back-menu').addEventListener('click', () => {
    window.showScreen("scr-1778907133295");
  });

  // モーダル閉じるボタンイベント
  container.querySelector('#btn-close-modal').addEventListener('click', () => {
    container.querySelector('#detail-modal').classList.add('hidden');
  });

  // 削除確認モーダルイベント
  container.querySelector('#btn-cancel-delete').addEventListener('click', () => {
    container.querySelector('#delete-modal').classList.add('hidden');
    deleteTargetId = null;
  });

  container.querySelector('#btn-confirm-delete').addEventListener('click', async () => {
    if (deleteTargetId) {
      await window.aivicApi.delete(1, deleteTargetId);
      const rows = await window.aivicApi.list(1);
      currentRecords = rows || [];
      renderRows(currentRecords);
      container.querySelector('#delete-modal').classList.add('hidden');
      deleteTargetId = null;
    }
  });

  // 行レベル操作のイベントデリゲーション
  container.addEventListener('click', async (e) => {
    // 詳細表示ボタン
    const detailBtn = e.target.closest('.detail-btn');
    if (detailBtn) {
      showDetail(detailBtn.dataset.id);
      return;
    }

    // 編集ボタン
    const editBtn = e.target.closest('.edit-btn');
    if (editBtn) {
      // 編集画面に遷移（記録IDをセッションストレージに保存）
      sessionStorage.setItem('editRecordId', editBtn.dataset.id);
      window.showScreen("scr-1778907343735");
      return;
    }

    // 削除ボタン
    const deleteBtn = e.target.closest('.delete-btn');
    if (deleteBtn) {
      deleteTargetId = deleteBtn.dataset.id;
      container.querySelector('#delete-modal').classList.remove('hidden');
      return;
    }
  });

  // モーダル背景クリックで閉じる
  container.querySelector('#detail-modal').addEventListener('click', (e) => {
    if (e.target.id === 'detail-modal') {
      container.querySelector('#detail-modal').classList.add('hidden');
    }
  });

  container.querySelector('#delete-modal').addEventListener('click', (e) => {
    if (e.target.id === 'delete-modal') {
      container.querySelector('#delete-modal').classList.add('hidden');
      deleteTargetId = null;
    }
  });
}

function(container, apiUrl, tables) {
  let mediaRecorder = null;
  let audioChunks = [];
  let isRecording = false;
  let selectedFile = null;
  let audioBlob = null;

  // DOM要素の取得
  const form = container.querySelector('#interruption-form');
  const startTimeInput = container.querySelector('#start-time');
  const endTimeInput = container.querySelector('#end-time');
  const reasonSelect = container.querySelector('#interruption-reason');
  const locationInput = container.querySelector('#interruption-location');
  const detailsTextarea = container.querySelector('#interruption-details');
  const durationDiv = container.querySelector('#interruption-duration');
  const charCountSpan = container.querySelector('#char-count');
  const photoUpload = container.querySelector('#photo-upload');
  const photoBtn = container.querySelector('#photo-btn');
  const photoPreview = container.querySelector('#photo-preview');
  const recordBtn = container.querySelector('#record-btn');
  const recordingStatus = container.querySelector('#recording-status');
  const audioPlayback = container.querySelector('#audio-playback');
  const selectAllCheckbox = container.querySelector('#select-all');
  const impactCheckboxes = container.querySelectorAll('input[name="impact"]');
  const tempSaveBtn = container.querySelector('#temp-save-btn');
  const completeBtn = container.querySelector('#complete-btn');
  const errorMessage = container.querySelector('#error-message');
  const relatedWork = container.querySelector('#related-work');

  // 現在時刻を中断開始時刻にセット
  const now = new Date();
  now.setMinutes(now.getMinutes() - now.getTimezoneOffset());
  startTimeInput.value = now.toISOString().slice(0, 16);

  // 関連作業項目の表示（仮データ）
  relatedWork.textContent = '設備点検作業 - A棟3階';

  // 文字数カウント
  detailsTextarea.addEventListener('input', () => {
    const count = detailsTextarea.value.length;
    charCountSpan.textContent = count;
    if (count > 1000) {
      charCountSpan.style.color = '#dc2626';
    } else {
      charCountSpan.style.color = 'var(--text-muted)';
    }
  });

  // 中断時間の自動計算
  function updateDuration() {
    const startTime = startTimeInput.value;
    const endTime = endTimeInput.value;

    if (startTime && endTime) {
      const start = new Date(startTime);
      const end = new Date(endTime);
      const diff = end - start;

      if (diff > 0) {
        const hours = Math.floor(diff / (1000 * 60 * 60));
        const minutes = Math.floor((diff % (1000 * 60 * 60)) / (1000 * 60));
        durationDiv.textContent = `${hours.toString().padStart(2, '0')}:${minutes.toString().padStart(2, '0')}`;
      } else {
        durationDiv.textContent = '無効な時間';
      }
    } else {
      durationDiv.textContent = '--:--';
    }
  }

  startTimeInput.addEventListener('change', updateDuration);
  endTimeInput.addEventListener('change', updateDuration);

  // 写真添付
  photoBtn.addEventListener('click', () => {
    photoUpload.click();
  });

  photoUpload.addEventListener('change', (e) => {
    const file = e.target.files[0];
    if (file) {
      // ファイルサイズチェック (10MB)
      if (file.size > 10 * 1024 * 1024) {
        showError('ファイルサイズは10MB以下にしてください');
        return;
      }

      // ファイル形式チェック
      if (!file.type.startsWith('image/')) {
        showError('画像ファイルのみアップロード可能です');
        return;
      }

      selectedFile = file;
      photoPreview.textContent = `選択済み: ${file.name}`;
      photoBtn.textContent = '📷 ' + file.name;
    }
  });

  // 音声録音
  recordBtn.addEventListener('click', async () => {
    if (!isRecording) {
      try {
        const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
        mediaRecorder = new MediaRecorder(stream);
        audioChunks = [];

        mediaRecorder.ondataavailable = (event) => {
          audioChunks.push(event.data);
        };

        mediaRecorder.onstop = () => {
          audioBlob = new Blob(audioChunks, { type: 'audio/wav' });
          const audioUrl = URL.createObjectURL(audioBlob);
          audioPlayback.src = audioUrl;
          audioPlayback.style.display = 'block';
          recordingStatus.textContent = '録音完了 - 再生して確認できます';
        };

        mediaRecorder.start();
        isRecording = true;
        recordBtn.textContent = '⏹️ 録音停止';
        recordingStatus.textContent = '録音中...';
      } catch (error) {
        showError('マイクにアクセスできません。ブラウザの設定を確認してください。');
      }
    } else {
      mediaRecorder.stop();
      mediaRecorder.stream.getTracks().forEach(track => track.stop());
      isRecording = false;
      recordBtn.textContent = '🎤 録音開始';
    }
  });

  // 全選択チェックボックス
  selectAllCheckbox.addEventListener('change', () => {
    impactCheckboxes.forEach(checkbox => {
      checkbox.checked = selectAllCheckbox.checked;
    });
  });

  // 個別チェックボックスの変更で全選択の状態を更新
  impactCheckboxes.forEach(checkbox => {
    checkbox.addEventListener('change', () => {
      const allChecked = Array.from(impactCheckboxes).every(cb => cb.checked);
      const noneChecked = Array.from(impactCheckboxes).every(cb => !cb.checked);

      if (allChecked) {
        selectAllCheckbox.checked = true;
        selectAllCheckbox.indeterminate = false;
      } else if (noneChecked) {
        selectAllCheckbox.checked = false;
        selectAllCheckbox.indeterminate = false;
      } else {
        selectAllCheckbox.checked = false;
        selectAllCheckbox.indeterminate = true;
      }
    });
  });

  // エラー表示
  function showError(message) {
    errorMessage.textContent = message;
    errorMessage.style.display = 'block';
    setTimeout(() => {
      errorMessage.style.display = 'none';
    }, 5000);
  }

  // バリデーション
  function validateForm() {
    const startTime = startTimeInput.value;
    const reason = reasonSelect.value;
    const details = detailsTextarea.value;

    if (!startTime) {
      showError('中断開始時刻は必須です');
      return false;
    }

    if (!reason) {
      showError('中断理由は必須です');
      return false;
    }

    // 未来時刻チェック
    const startDate = new Date(startTime);
    const now = new Date();
    if (startDate > now) {
      showError('未来の時刻は入力できません');
      return false;
    }

    // 文字数チェック
    if (details.length > 1000) {
      showError('中断詳細は1000文字以内で入力してください');
      return false;
    }

    return true;
  }

  // フォームデータ収集
  function collectFormData() {
    const urgencyRadio = container.querySelector('input[name="urgency"]:checked');
    const impactValues = Array.from(impactCheckboxes)
      .filter(cb => cb.checked)
      .map(cb => cb.value);

    return {
      中断開始日時: startTimeInput.value,
      中断終了日時: endTimeInput.value || null,
      中断理由区分: reasonSelect.value,
      中断理由詳細: detailsTextarea.value,
      中断時間: calculateDurationMinutes(),
      影響度: urgencyRadio ? urgencyRadio.value : '低',
      対応状況: '対応中',
      記録者ID: 'current-user-id', // 実際の実装では認証情報から取得
      作業記録ID: 'current-work-record-id' // 実際の実装では現在の作業記録から取得
    };
  }

  function calculateDurationMinutes() {
    const startTime = startTimeInput.value;
    const endTime = endTimeInput.value;

    if (startTime && endTime) {
      const start = new Date(startTime);
      const end = new Date(endTime);
      const diff = end - start;
      return Math.floor(diff / (1000 * 60));
    }
    return null;
  }

  // 一時保存
  tempSaveBtn.addEventListener('click', async () => {
    if (!validateForm()) return;

    const formData = collectFormData();
    formData.対応状況 = '一時保存';

    try {
      const saved = await window.aivicApi.save(2, formData); // 中断記録テーブル
      if (saved) {
        alert('一時保存しました');
      } else {
        showError('一時保存に失敗しました');
      }
    } catch (error) {
      showError('ネットワークエラーが発生しました');
    }
  });

  // 記録完了
  completeBtn.addEventListener('click', async () => {
    if (!validateForm()) return;

    const formData = collectFormData();

    try {
      const saved = await window.aivicApi.save(2, formData); // 中断記録テーブル
      if (saved) {
        alert('中断記録を完了しました');
        window.showScreen("scr-1778907251446"); // 作業再開記録画面
      } else {
        showError('記録の保存に失敗しました');
      }
    } catch (error) {
      showError('ネットワークエラーが発生しました');
    }
  });

  // 一時保存データの復元（ページ読み込み時）
  async function loadTempData() {
    try {
      const records = await window.aivicApi.list(2);
      if (records) {
        const tempRecord = records.find(r => r.対応状況 === '一時保存');
        if (tempRecord) {
          startTimeInput.value = tempRecord.中断開始日時 || '';
          endTimeInput.value = tempRecord.中断終了日時 || '';
          reasonSelect.value = tempRecord.中断理由区分 || '';
          detailsTextarea.value = tempRecord.中断理由詳細 || '';
          locationInput.value = tempRecord.中断場所 || '';

          // 緊急度の復元
          const urgencyRadio = container.querySelector(`input[name="urgency"][value="${tempRecord.影響度}"]`);
          if (urgencyRadio) urgencyRadio.checked = true;

          updateDuration();
        }
      }
    } catch (error) {
      console.log('一時保存データの読み込みに失敗しました');
    }
  }

  // 初期化
  loadTempData();
}

function(container, apiUrl, tables) {
  let selectedWorkRecord = null;
  let selectedSuspendRecord = null;

  // 現在時刻を設定
  function setCurrentTime() {
    const now = new Date();
    const localDateTime = new Date(now.getTime() - now.getTimezoneOffset() * 60000).toISOString().slice(0, 16);
    container.querySelector('#resume-time').value = localDateTime;
  }

  // 中断中作業一覧を描画
  function renderSuspendedWorks(workRecords, suspendRecords) {
    const tbody = container.querySelector('#suspended-work-tbody');
    const noWorkDiv = container.querySelector('#no-suspended-work');

    // 中断中の作業記録を抽出（進捗状況が「中断」のもの）
    const suspendedWorks = workRecords.filter(work => work.進捗状況 === '中断');

    if (suspendedWorks.length === 0) {
      tbody.innerHTML = '';
      noWorkDiv.classList.remove('hidden');
      return;
    }

    noWorkDiv.classList.add('hidden');
    tbody.innerHTML = suspendedWorks.map(work => {
      // 対応する中断記録を取得
      const suspendRecord = suspendRecords.find(s => s.作業記録ID === work.作業記録ID && !s.中断終了日時);
      const suspendTime = suspendRecord ? new Date(suspendRecord.中断開始日時).toLocaleString() : '-';
      const suspendReason = suspendRecord ? (suspendRecord.中断理由詳細 || suspendRecord.中断理由区分 || '-') : '-';

      return `
        <tr data-work-id="${work.作業記録ID}" data-suspend-id="${suspendRecord?.中断記録ID || ''}" style="cursor: pointer;">
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${work.作業内容 || work.プロジェクト名 || '-'}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${suspendTime}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${suspendReason}</td>
          <td style="padding: 6px 10px;">
            <button class="action-btn select-work-btn" data-work-id="${work.作業記録ID}" data-suspend-id="${suspendRecord?.中断記録ID || ''}" style="padding: 4px 8px; font-size: 12px;">選択</button>
          </td>
        </tr>
      `;
    }).join('');
  }

  // 作業選択時の処理
  function selectWork(workId, suspendId) {
    Promise.all([
      window.aivicApi.list(1), // 作業記録
      window.aivicApi.list(2)  // 中断記録
    ]).then(([workRecords, suspendRecords]) => {
      selectedWorkRecord = workRecords.find(w => w.作業記録ID === workId);
      selectedSuspendRecord = suspendRecords.find(s => s.中断記録ID === suspendId);

      if (selectedWorkRecord) {
        // 選択された作業の情報を表示
        container.querySelector('#selected-work-name').textContent = selectedWorkRecord.作業内容 || selectedWorkRecord.プロジェクト名 || '-';
        container.querySelector('#selected-suspend-time').textContent = selectedSuspendRecord ? 
          new Date(selectedSuspendRecord.中断開始日時).toLocaleString() : '-';
        container.querySelector('#selected-suspend-reason').textContent = selectedSuspendRecord ? 
          (selectedSuspendRecord.中断理由詳細 || selectedSuspendRecord.中断理由区分 || '-') : '-';

        // 再開時刻を現在時刻に設定
        setCurrentTime();

        // フォームを表示
        container.querySelector('#resume-form').classList.remove('hidden');
      }
    });
  }

  // 文字数カウント
  function updateCharCount() {
    const textarea = container.querySelector('#resume-reason-detail');
    const charCount = container.querySelector('#char-count');
    const errorDiv = container.querySelector('#resume-reason-error');

    const length = textarea.value.length;
    charCount.textContent = `${length}/500`;

    if (length > 500) {
      errorDiv.textContent = '再開理由は500文字以内で入力してください';
      errorDiv.classList.remove('hidden');
      charCount.style.color = '#ff6b6b';
    } else {
      errorDiv.classList.add('hidden');
      charCount.style.color = 'var(--text-muted)';
    }
  }

  // バリデーション
  function validateForm() {
    const reasonSelect = container.querySelector('#resume-reason-select').value;
    const reasonDetail = container.querySelector('#resume-reason-detail').value.trim();
    const errorDiv = container.querySelector('#resume-reason-error');

    if (!reasonSelect && !reasonDetail) {
      errorDiv.textContent = '再開理由を選択するか詳細を入力してください';
      errorDiv.classList.remove('hidden');
      return false;
    }

    if (reasonDetail.length > 500) {
      errorDiv.textContent = '再開理由は500文字以内で入力してください';
      errorDiv.classList.remove('hidden');
      return false;
    }

    errorDiv.classList.add('hidden');
    return true;
  }

  // 確認ダイアログを表示
  function showConfirmDialog() {
    const dialog = container.querySelector('#resume-confirm-dialog');
    const confirmInfo = container.querySelector('#confirm-work-info');

    const workName = selectedWorkRecord.作業内容 || selectedWorkRecord.プロジェクト名 || '-';
    const resumeTime = new Date(container.querySelector('#resume-time').value).toLocaleString();

    confirmInfo.innerHTML = `
      <div><strong>作業項目:</strong> ${workName}</div>
      <div><strong>再開時刻:</strong> ${resumeTime}</div>
    `;

    dialog.classList.remove('hidden');
  }

  // 作業再開処理
  async function resumeWork() {
    if (!selectedWorkRecord || !selectedSuspendRecord) return;

    try {
      const resumeTime = container.querySelector('#resume-time').value;
      const reasonSelect = container.querySelector('#resume-reason-select').value;
      const reasonDetail = container.querySelector('#resume-reason-detail').value.trim();
      const finalReason = reasonDetail || reasonSelect;

      // 中断記録を終了
      await window.aivicApi.update(2, selectedSuspendRecord.中断記録ID, {
        中断終了日時: new Date(resumeTime).toISOString(),
        中断時間: Math.floor((new Date(resumeTime) - new Date(selectedSuspendRecord.中断開始日時)) / 60000),
        対応状況: '解決済み'
      });

      // 作業記録の進捗状況を「作業中」に更新
      await window.aivicApi.update(1, selectedWorkRecord.作業記録ID, {
        進捗状況: '作業中'
      });

      // 成功メッセージ
      alert('作業を再開しました');

      // 工数入力画面に遷移
      window.showScreen("scr-1778907296658");

    } catch (error) {
      console.error('作業再開エラー:', error);
      alert('作業再開に失敗しました');
    }
  }

  // 初期データ読み込み
  Promise.all([
    window.aivicApi.list(1), // 作業記録
    window.aivicApi.list(2)  // 中断記録
  ]).then(([workRecords, suspendRecords]) => {
    renderSuspendedWorks(workRecords || [], suspendRecords || []);
  });

  // イベントリスナー
  container.addEventListener('click', (e) => {
    // 作業選択ボタン
    const selectBtn = e.target.closest('.select-work-btn');
    if (selectBtn) {
      const workId = selectBtn.dataset.workId;
      const suspendId = selectBtn.dataset.suspendId;
      selectWork(workId, suspendId);
      return;
    }
  });

  // 戻るボタン
  container.querySelector('#btn-back').addEventListener('click', () => {
    history.back();
  });

  // キャンセルボタン
  container.querySelector('#btn-cancel').addEventListener('click', () => {
    container.querySelector('#resume-form').classList.add('hidden');
    selectedWorkRecord = null;
    selectedSuspendRecord = null;
  });

  // 作業再開ボタン
  container.querySelector('#btn-resume').addEventListener('click', () => {
    if (validateForm()) {
      showConfirmDialog();
    }
  });

  // 確認ダイアログのボタン
  container.querySelector('#btn-dialog-cancel').addEventListener('click', () => {
    container.querySelector('#resume-confirm-dialog').classList.add('hidden');
  });

  container.querySelector('#btn-dialog-ok').addEventListener('click', () => {
    container.querySelector('#resume-confirm-dialog').classList.add('hidden');
    resumeWork();
  });

  // 文字数カウント
  container.querySelector('#resume-reason-detail').addEventListener('input', updateCharCount);

  // 再開理由選択時の処理
  container.querySelector('#resume-reason-select').addEventListener('change', (e) => {
    const errorDiv = container.querySelector('#resume-reason-error');
    if (e.target.value) {
      errorDiv.classList.add('hidden');
    }
  });
}

function(container, apiUrl, tables) {
  let currentCheckResult = null;
  let currentErrors = [];

  // チェック結果を表示する関数
  function displayCheckResult(result) {
    currentCheckResult = result;
    currentErrors = result.errors || [];

    const statusIcon = container.querySelector('#status-icon');
    const statusText = container.querySelector('#status-text');
    const saveStatus = container.querySelector('#save-status');

    // ステータスアイコンとテキストの更新
    if (result.hasErrors) {
      statusIcon.style.background = '#ef4444';
      statusIcon.textContent = '✗';
      statusText.textContent = 'チェック失敗';
      statusText.style.color = '#ef4444';
      saveStatus.textContent = '保存可否: 保存不可';
      saveStatus.style.color = '#ef4444';
    } else {
      statusIcon.style.background = '#10b981';
      statusIcon.textContent = '✓';
      statusText.textContent = 'チェック通過';
      statusText.style.color = '#10b981';
      saveStatus.textContent = '保存可否: 保存可能';
      saveStatus.style.color = '#10b981';
    }

    // 各チェック結果エリアの更新
    updateCheckArea('required-check-area', result.requiredCheck);
    updateCheckArea('format-error-area', result.formatErrors);
    updateCheckArea('datetime-check-area', result.datetimeCheck);
    updateCheckArea('worktime-warning-area', result.worktimeWarning);
    updateCheckArea('duplicate-alert-area', result.duplicateAlert);
    updateCheckArea('anomaly-notification-area', result.anomalyNotification);

    // 修正提案の表示
    const suggestionArea = container.querySelector('#correction-suggestion-area');
    if (result.suggestions && result.suggestions.length > 0) {
      suggestionArea.innerHTML = result.suggestions.map(s => 
        `<div style="margin-bottom: 4px; padding: 4px 8px; background: rgba(59, 130, 246, 0.1); border-radius: 4px; border-left: 2px solid #3b82f6;">
          <strong style="color: var(--text);">${s.field}:</strong> <span style="color: var(--text-muted);">${s.suggestion}</span>
        </div>`
      ).join('');
    } else {
      suggestionArea.innerHTML = '<span style="color: var(--text-muted);">修正提案はありません</span>';
    }
  }

  function updateCheckArea(areaId, checkResult) {
    const area = container.querySelector(`#${areaId}`);
    if (!checkResult) {
      area.innerHTML = '<span style="color: var(--text-muted);">チェック対象なし</span>';
      return;
    }

    if (checkResult.status === 'ok') {
      area.innerHTML = `<div style="color: #10b981;">✓ ${checkResult.message || 'チェック通過'}</div>`;
    } else if (checkResult.status === 'warning') {
      area.innerHTML = `<div style="color: #f59e0b;">⚠ ${checkResult.message}</div>`;
    } else {
      area.innerHTML = `<div style="color: #ef4444;">✗ ${checkResult.message}</div>`;
    }
  }

  // 模擬チェック処理
  async function performInputCheck(recordId) {
    if (!recordId.trim()) {
      alert('作業記録IDを入力してください');
      return;
    }

    // 作業記録データを取得
    const workRecords = await window.aivicApi.list(1); // 作業記録テーブル
    const targetRecord = workRecords?.find(r => r.作業記録ID === recordId);

    if (!targetRecord) {
      alert('指定された作業記録IDが見つかりません');
      return;
    }

    const result = {
      hasErrors: false,
      errors: [],
      suggestions: []
    };

    // 必須項目チェック
    const requiredFields = ['作業日', '作業開始時刻', '作業終了時刻', '作業内容', '作業場所'];
    const missingFields = requiredFields.filter(field => !targetRecord[field]);

    if (missingFields.length > 0) {
      result.hasErrors = true;
      result.requiredCheck = {
        status: 'error',
        message: `必須項目が未入力: ${missingFields.join(', ')}`
      };
      result.errors.push(`必須項目未入力: ${missingFields.join(', ')}`);
      missingFields.forEach(field => {
        result.suggestions.push({
          field: field,
          suggestion: `${field}を入力してください`
        });
      });
    } else {
      result.requiredCheck = { status: 'ok', message: '全ての必須項目が入力されています' };
    }

    // 日時形式チェック
    const dateTimePattern = /^\d{4}-\d{2}-\d{2} \d{2}:\d{2}$/;
    const formatErrors = [];

    if (targetRecord.作業開始時刻&& !dateTimePattern.test(targetRecord.作業開始時刻)) {
      formatErrors.push('作業開始時刻');
    }
    if (targetRecord.作業終了時刻 && !dateTimePattern.test(targetRecord.作業終了時刻)) {
      formatErrors.push('作業終了時刻');
    }

    if (formatErrors.length > 0) {
      result.hasErrors = true;
      result.formatErrors = {
        status: 'error',
        message: `日時形式エラー: ${formatErrors.join(', ')}`
      };
      result.errors.push(`日時形式エラー: ${formatErrors.join(', ')}`);
      formatErrors.forEach(field => {
        result.suggestions.push({
          field: field,
          suggestion: 'YYYY-MM-DD HH:MM形式で入力してください（例: 2024-01-15 09:00）'
        });
      });
    } else {
      result.formatErrors = { status: 'ok', message: '日時形式は正常です' };
    }

    // 日時整合性チェック
    if (targetRecord.作業開始時刻&& targetRecord.作業終了時刻) {
      const startTime = new Date(targetRecord.作業開始時刻);
      const endTime = new Date(targetRecord.作業終了時刻);

      if (startTime >= endTime) {
        result.hasErrors = true;
        result.datetimeCheck = {
          status: 'error',
          message: '開始時刻は終了時刻より前に設定してください'
        };
        result.errors.push('開始時刻が終了時刻より後になっています');
        result.suggestions.push({
          field: '作業時間',
          suggestion: '開始時刻と終了時刻を正しい順序で入力してください'
        });
      } else {
        result.datetimeCheck = { status: 'ok', message: '日時の整合性は正常です' };
      }
    } else {
      result.datetimeCheck = { status: 'warning', message: '日時が不完全なため整合性チェックをスキップしました' };
    }

    // 作業時間妥当性チェック
    if (targetRecord.作業時間) {
      const workMinutes = parseInt(targetRecord.作業時間);
      if (workMinutes < 1) {
        result.hasErrors = true;
        result.worktimeWarning = {
          status: 'error',
          message: '作業時間が異常に短く設定されています（1分未満）'
        };
        result.errors.push('作業時間が1分未満です');
        result.suggestions.push({
          field: '作業時間',
          suggestion: '作業時間は1分以上で入力してください'
        });
      } else if (workMinutes > 1440) { // 24時間 = 1440分
        result.hasErrors = true;
        result.worktimeWarning = {
          status: 'error',
          message: '作業時間が異常に長く設定されています（24時間超過）'
        };
        result.errors.push('作業時間が24時間を超えています');
        result.suggestions.push({
          field: '作業時間',
          suggestion: '作業時間は24時間以内で入力してください'
        });
      } else if (workMinutes < 5) {
        result.worktimeWarning = {
          status: 'warning',
          message: '作業時間が短めです（5分未満）。内容を確認してください'
        };
      } else if (workMinutes > 720) { // 12時間
        result.worktimeWarning = {
          status: 'warning',
          message: '作業時間が長めです（12時間超過）。内容を確認してください'
        };
      } else {
        result.worktimeWarning = { status: 'ok', message: '作業時間は適切な範囲です' };
      }
    }

    // 重複データチェック
    const duplicates = workRecords?.filter(r => 
      r.作業記録ID !== recordId &&
      r.作業員ID === targetRecord.作業員ID &&
      r.作業開始時刻=== targetRecord.作業開始時刻
    ) || [];

    if (duplicates.length > 0) {
      result.hasErrors = true;
      result.duplicateAlert = {
        status: 'error',
        message: `同一日時の重複データが${duplicates.length}件検出されました`
      };
      result.errors.push(`重複データ${duplicates.length}件`);
      result.suggestions.push({
        field: '作業日時',
        suggestion: '別の日時を指定するか、既存データを確認してください'
      });
    } else {
      result.duplicateAlert = { status: 'ok', message: '重複データは検出されませんでした' };
    }

    // 異常値検出（文字数制限など）
    const anomalies = [];
    if (targetRecord.作業内容 && targetRecord.作業内容.length > 200) {
      anomalies.push('作業内容が最大文字数を超過');
    }
    if (targetRecord.備考 && targetRecord.備考.length > 500) {
      anomalies.push('備考が最大文字数を超過');
    }

    if (anomalies.length > 0) {
      result.hasErrors = true;
      result.anomalyNotification = {
        status: 'error',
        message: `異常値検出: ${anomalies.join(', ')}`
      };
      result.errors.push(...anomalies);
      result.suggestions.push({
        field: '入力内容',
        suggestion: '文字数制限を確認し、適切な長さに調整してください'
      });
    } else {
      result.anomalyNotification = { status: 'ok', message: '異常値は検出されませんでした' };
    }

    displayCheckResult(result);

    // 異常値検出ログに記録
    if (result.hasErrors) {
      const logData = {
        検出対象テーブル: '作業記録',
        検出対象レコードID: recordId,
        ユーザーID: targetRecord.作業員ID || 'unknown',
        異常値種別: result.errors.join(', '),
        検出項目: Object.keys(targetRecord).join(', '),
        検出値: JSON.stringify(targetRecord),
        閾値: '標準チェック基準',
        重要度: result.hasErrors ? '高' : '中',
        確認状況: '未確認',
        通知送信フラグ: true,
        検出日時: new Date().toISOString(),
        作成日時: new Date().toISOString(),
        更新日時: new Date().toISOString()
      };

      await window.aivicApi.save(4, logData); // 異常値検出ログテーブル
    }
  }

  // エラー詳細表示
  function showErrorDetail() {
    const modal = container.querySelector('#error-detail-modal');
    const content = container.querySelector('#error-detail-content');

    if (currentErrors.length === 0) {
      content.innerHTML = '<p style="color: var(--text-muted);">エラーはありません</p>';
    } else {
      content.innerHTML = currentErrors.map((error, index) => 
        `<div style="margin-bottom: 8px; padding: 8px; background: rgba(239, 68, 68, 0.1); border-radius: 4px; border-left: 2px solid #ef4444;">
          <strong style="color: #ef4444;">エラー ${index + 1}:</strong> 
          <span style="color: var(--text);">${error}</span>
        </div>`
      ).join('');
    }

    modal.classList.remove('hidden');
  }

  // エラーログ出力
  async function exportErrorLog() {
    const logs = await window.aivicApi.list(4); // 異常値検出ログテーブル
    if (!logs || logs.length === 0) {
      alert('出力するエラーログがありません');
      return;
    }

    const headers = ['検出日時', '対象テーブル', '対象レコードID', '異常値種別', '重要度', '確認状況'];
    const csvContent = '\uFEFF' + [
      headers.join(','),
      ...logs.map(log => [
        log.検出日時 || '',
        log.検出対象テーブル || '',
        log.検出対象レコードID || '',
        log.異常値種別 || '',
        log.重要度 || '',
        log.確認状況 || ''
      ].map(field => `"${field}"`).join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `error_log_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // イベントリスナー設定
  container.querySelector('#btn-check').addEventListener('click', () => {
    const recordId = container.querySelector('#target-record-id').value;
    performInputCheck(recordId);
  });

  container.querySelector('#btn-error-detail').addEventListener('click', showErrorDetail);

  container.querySelector('#btn-export-log').addEventListener('click', exportErrorLog);

  container.querySelector('#btn-to-correction').addEventListener('click', () => {
    window.showScreen('scr-1778907319067'); // 修正入力画面
  });

  container.querySelector('#btn-close-modal').addEventListener('click', () => {
    container.querySelector('#error-detail-modal').classList.add('hidden');
  });

  // モーダル背景クリックで閉じる
  container.querySelector('#error-detail-modal').addEventListener('click', (e) => {
    if (e.target === container.querySelector('#error-detail-modal')) {
      container.querySelector('#error-detail-modal').classList.add('hidden');
    }
  });

  // 入力フィールドフォーカス時のガイダンス表示
  container.querySelector('#target-record-id').addEventListener('focus', () => {
    const panel = container.querySelector('#guidance-panel');
    panel.style.borderLeft = '3px solid var(--primary)';
    panel.style.background = 'rgba(59, 130, 246, 0.05)';
  });

  container.querySelector('#target-record-id').addEventListener('blur', () => {
    const panel = container.querySelector('#guidance-panel');
    panel.style.borderLeft = '3px solid var(--primary)';
    panel.style.background = 'var(--bg-card)';
  });
}

function(container, apiUrl, tables) {
  // エラー情報を格納する変数
  let errorInfo = {
    code: 'E001',
    message: '申し訳ございません。予期しないエラーが発生しました。しばらく時間をおいて再度お試しください。',
    timestamp: new Date().toLocaleString('ja-JP'),
    type: 'システムエラー',
    location: 'データ処理モジュール',
    userId: 'user_001',
    sessionId: 'sess_abc123',
    requestId: 'req_xyz789',
    technicalDetails: 'Network connection timeout after 30 seconds',
    retryCount: 0
  };

  // URLパラメータからエラー情報を取得
  const urlParams = new URLSearchParams(window.location.search);
  if (urlParams.get('error')) {
    try {
      const errorData = JSON.parse(decodeURIComponent(urlParams.get('error')));
      errorInfo = { ...errorInfo, ...errorData };
    } catch (e) {
      console.warn('エラー情報の解析に失敗しました:', e);
    }
  }

  // エラー情報を画面に反映
  function updateErrorDisplay() {
    container.querySelector('#error-message-text').textContent = errorInfo.message;
    container.querySelector('#error-code').textContent = errorInfo.code;
    container.querySelector('#error-timestamp').textContent = errorInfo.timestamp;
    container.querySelector('#error-type').textContent = errorInfo.type;
    container.querySelector('#error-location').textContent = errorInfo.location;
    container.querySelector('#error-user-id').textContent = errorInfo.userId;
    container.querySelector('#error-session-id').textContent = errorInfo.sessionId;
    container.querySelector('#error-request-id').textContent = errorInfo.requestId;
    container.querySelector('#error-technical-details').textContent = errorInfo.technicalDetails;
  }

  // 初期表示
  updateErrorDisplay();

  // 再試行ボタン
  container.querySelector('#btn-retry').addEventListener('click', async function() {
    const button = this;
    const originalText = button.textContent;

    // ボタンを無効化して重複実行を防止
    button.disabled = true;
    button.textContent = '再試行中...';
    button.style.background = 'var(--text-muted)';

    try {
      errorInfo.retryCount++;

      // ネットワーク接続チェック
      if (!navigator.onLine) {
        throw new Error('ネットワーク接続がありません');
      }

      // 簡単な接続テスト
      const response = await fetch(apiUrl + '/api/health', { 
        method: 'GET',
        timeout: 5000 
      });

      if (response.ok) {
        // 成功時は前の画面に戻る
        window.history.back();
      } else {
        throw new Error('サーバーに接続できません');
      }
    } catch (error) {
      // 再試行失敗
      errorInfo.message = `再試行に失敗しました (${errorInfo.retryCount}回目)。${error.message}`;
      errorInfo.timestamp = new Date().toLocaleString('ja-JP');
      updateErrorDisplay();

      // エラーメッセージを一時的に表示
      const messageEl = container.querySelector('#error-message-text');
      const originalMessage = messageEl.textContent;
      messageEl.textContent = '再試行に失敗しました。ネットワーク接続を確認してください。';
      messageEl.style.color = '#dc2626';

      setTimeout(() => {
        messageEl.textContent = originalMessage;
        messageEl.style.color = 'var(--text)';
      }, 3000);
    } finally {
      // ボタンを再有効化
      button.disabled = false;
      button.textContent = originalText;
      button.style.background = 'var(--primary)';
    }
  });

  // 戻るボタン
  container.querySelector('#btn-back').addEventListener('click', function() {
    if (window.history.length > 1) {
      window.history.back();
    } else {
      // 履歴がない場合はホーム画面に遷移
      window.showScreen('scr-1778907133295'); // 工数記録画面
    }
  });

  // ホームに戻るボタン
  container.querySelector('#btn-home').addEventListener('click', function() {
    window.showScreen('scr-1778907133295'); // 工数記録画面
  });

  // 管理者に連絡ボタン
  container.querySelector('#btn-contact-admin').addEventListener('click', async function() {
    try {
      // 管理者連絡機能の利用可能性をチェック
      const response = await fetch(apiUrl + '/api/contact/check', {
        method: 'GET',
        timeout: 3000
      });

      if (response.ok) {
        // 緊急報告画面に遷移
        window.showScreen('scr-1778907330826');
      } else {
        throw new Error('連絡機能が利用できません');
      }
    } catch (error) {
      // 連絡機能が利用できない場合は代替連絡先を表示
      const fallbackEl = container.querySelector('#contact-fallback');
      fallbackEl.classList.remove('hidden');

      // 3秒後に自動で隠す
      setTimeout(() => {
        fallbackEl.classList.add('hidden');
      }, 10000);
    }
  });

  // エラー詳細表示ボタン
  container.querySelector('#btn-show-details').addEventListener('click', async function() {
    const detailsEl = container.querySelector('#error-details');
    const button = this;

    if (detailsEl.classList.contains('hidden')) {
      try {
        // エラー詳細情報を取得を試行
        const response = await fetch(apiUrl + '/api/errors/' + errorInfo.requestId, {
          method: 'GET',
          timeout: 3000
        });

        if (response.ok) {
          const detailData = await response.json();
          // 取得した詳細情報で更新
          if (detailData.technicalDetails) {
            container.querySelector('#error-technical-details').textContent = detailData.technicalDetails;
          }
        }
      } catch (error) {
        // 詳細情報が取得できない場合のメッセージ
        container.querySelector('#error-technical-details').textContent = 'エラーの詳細情報を取得できませんでした。';
      }

      detailsEl.classList.remove('hidden');
      button.textContent = 'エラー詳細を隠す';
    } else {
      detailsEl.classList.add('hidden');
      button.textContent = 'エラー詳細表示';
    }
  });

  // セッション切れの検出
  function checkSessionStatus() {
    const token = localStorage.getItem('authToken') || sessionStorage.getItem('authToken');
    if (!token) {
      // セッション切れの場合は特別な表示
      errorInfo.message = 'セッションが切れました。再度ログインしてください。';
      errorInfo.code = 'E401';
      updateErrorDisplay();

      // ログイン画面への遷移ボタンを追加
      const actionsEl = container.querySelector('.error-actions');
      const loginBtn = document.createElement('button');
      loginBtn.textContent = 'ログイン画面へ';
      loginBtn.className = 'action-btn';
      loginBtn.style.cssText = 'background: var(--primary); color: #fff; border: none; padding: 6px 14px; border-radius: 6px; font-size: 13px; font-weight: 500; cursor: pointer;';
      loginBtn.addEventListener('click', () => {
        window.location.href = './login.html';
      });
      actionsEl.appendChild(loginBtn);
    }
  }

  // 初期化時にセッション状態をチェック
  checkSessionStatus();

  // 長いエラーメッセージの制限処理
  function limitErrorMessage() {
    const messageEl = container.querySelector('#error-message-text');
    const maxLength = 500;

    if (errorInfo.message.length > maxLength) {
      const truncated = errorInfo.message.substring(0, maxLength) + '...';
      messageEl.textContent = truncated;
      messageEl.title = errorInfo.message; // フルメッセージをツールチップで表示
    }
  }

  limitErrorMessage();

  // ネットワーク状態の監視
  window.addEventListener('online', () => {
    const messageEl = container.querySelector('#error-message-text');
    messageEl.textContent = 'ネットワーク接続が復旧しました。再試行してください。';
    messageEl.style.color = '#059669';

    setTimeout(() => {
      messageEl.style.color = 'var(--text)';
      updateErrorDisplay();
    }, 3000);
  });

  window.addEventListener('offline', () => {
    const messageEl = container.querySelector('#error-message-text');
    messageEl.textContent = 'ネットワーク接続が切断されました。';
    messageEl.style.color = '#dc2626';
  });
}

function(container, apiUrl, tables) {
  let interruptRecords = [];

  // 現在のユーザー情報を設定
  const currentUser = { id: 'user-001', name: '田中太郎' };
  container.querySelector('#worker-name').value = currentUser.name;

  // 作業項目の選択肢を設定
  function loadWorkItems() {
    const workItemSelect = container.querySelector('#work-item');
    const workItems = tables[3]?.records || [];
    workItems.forEach(item => {
      const option = document.createElement('option');
      option.value = item.作業項目ID;
      option.textContent = item.作業項目名;
      workItemSelect.appendChild(option);
    });
  }

  // 実働時間の計算
  function calculateWorkTime() {
    const startTime = container.querySelector('#start-time').value;
    const endTime = container.querySelector('#end-time').value;
    const breakTime = parseInt(container.querySelector('#break-time').value) || 0;

    if (!startTime || !endTime) {
      container.querySelector('#actual-work-time').value = '';
      return;
    }

    const start = new Date(`2000-01-01T${startTime}`);
    let end = new Date(`2000-01-01T${endTime}`);

    // 24時間をまたぐ場合
    if (end <= start) {
      end.setDate(end.getDate() + 1);
    }

    const diffMs = end - start;
    const diffMinutes = Math.floor(diffMs / (1000 * 60));
    const actualMinutes = diffMinutes - breakTime;

    if (actualMinutes < 0) {
      container.querySelector('#actual-work-time').value = '';
      return;
    }

    const hours = Math.floor(actualMinutes / 60);
    const minutes = actualMinutes % 60;
    container.querySelector('#actual-work-time').value = `${hours}時間${minutes.toString().padStart(2, '0')}分`;
  }

  // 文字数カウント
  function updateCharCount() {
    const textarea = container.querySelector('#work-details');
    const charCount = container.querySelector('#char-count');
    charCount.textContent = textarea.value.length;
  }

  // エラーメッセージ表示
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    errorDiv.textContent = message;
    errorDiv.style.display = 'block';
    setTimeout(() => {
      errorDiv.style.display = 'none';
    }, 5000);
  }

  // バリデーション
  function validateForm() {
    const workDate = container.querySelector('#work-date').value;
    const workItem = container.querySelector('#work-item').value;
    const startTime = container.querySelector('#start-time').value;
    const endTime = container.querySelector('#end-time').value;
    const workLocation = container.querySelector('#work-location').value;
    const workDetails = container.querySelector('#work-details').value;
    const breakTime = parseInt(container.querySelector('#break-time').value) || 0;

    if (!workDate) {
      showError('作業日付を入力してください');
      return false;
    }

    // 未来日付チェック
    const today = new Date().toISOString().split('T')[0];
    if (workDate > today) {
      showError('未来の日付は選択できません');
      return false;
    }

    if (!workItem) {
      showError('作業項目を選択してください');
      return false;
    }

    if (!startTime) {
      showError('開始時刻を入力してください');
      return false;
    }

    if (!endTime) {
      showError('終了時刻を入力してください');
      return false;
    }

    if (!workLocation) {
      showError('作業場所を入力してください');
      return false;
    }

    if (!workDetails) {
      showError('作業内容詳細を入力してください');
      return false;
    }

    if (workDetails.length > 500) {
      showError('作業内容詳細は500文字以内で入力してください');
      return false;
    }

    // 時刻フォーマットチェック
    const timeRegex = /^([01]?[0-9]|2[0-3]):[0-5][0-9]$/;
    if (!timeRegex.test(startTime) || !timeRegex.test(endTime)) {
      showError('時刻の形式が正しくありません');
      return false;
    }

    // 開始終了時刻チェック
    if (startTime === endTime) {
      showError('開始時刻と終了時刻が同じです');
      return false;
    }

    // 実働時間計算
    const start = new Date(`2000-01-01T${startTime}`);
    let end = new Date(`2000-01-01T${endTime}`);
    if (end <= start) {
      end.setDate(end.getDate() + 1);
    }

    const diffMs = end - start;
    const diffMinutes = Math.floor(diffMs / (1000 * 60));

    if (breakTime > diffMinutes) {
      showError('休憩時間が実働時間を超過しています');
      return false;
    }

    // 中断時間の合計チェック
    const totalInterruptTime = interruptRecords.reduce((sum, record) => {
      if (record.中断終了日時) {
        const interruptStart = new Date(`2000-01-01T${record.中断開始日時.split('T')[1]}`);
        const interruptEnd = new Date(`2000-01-01T${record.中断終了日時.split('T')[1]}`);
        const interruptMinutes = Math.floor((interruptEnd - interruptStart) / (1000 * 60));
        return sum + interruptMinutes;
      }
      return sum;
    }, 0);

    if (totalInterruptTime >= diffMinutes) {
      showError('中断時間の合計が実働時間と一致または超過しています');
      return false;
    }

    return true;
  }

  // 中断記録の描画
  function renderInterruptRecords() {
    const tbody = container.querySelector('#interrupt-tbody');
    tbody.innerHTML = interruptRecords.map((record, index) => {
      const startTime = record.中断開始日時 ? new Date(record.中断開始日時).toLocaleTimeString('ja-JP', {hour: '2-digit', minute: '2-digit'}) : '';
      const endTime = record.中断終了日時 ? new Date(record.中断終了日時).toLocaleTimeString('ja-JP', {hour: '2-digit', minute: '2-digit'}) : '';
      let duration = '';
      if (record.中断開始日時 && record.中断終了日時) {
        const start = new Date(record.中断開始日時);
        const end = new Date(record.中断終了日時);
        const minutes = Math.floor((end - start) / (1000 * 60));
        duration = `${Math.floor(minutes / 60)}時間${(minutes % 60).toString().padStart(2, '0')}分`;
      }

      return `
        <tr>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text); border-bottom: 1px solid rgba(255,255,255,0.05);">${record.中断理由区分 || ''}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text); border-bottom: 1px solid rgba(255,255,255,0.05);">${startTime}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text); border-bottom: 1px solid rgba(255,255,255,0.05);">${endTime}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text); border-bottom: 1px solid rgba(255,255,255,0.05);">${duration}</td>
          <td style="padding: 6px 10px; font-size: 13px; border-bottom: 1px solid rgba(255,255,255,0.05);">
            <button class="action-btn secondary delete-interrupt-btn" data-index="${index}" style="background: transparent; color: var(--text); border: 1px solid rgba(255,255,255,0.18); padding: 4px 8px; border-radius: 4px; font-size: 11px; cursor: pointer;">削除</button>
          </td>
        </tr>
      `;
    }).join('');
  }

  // 初期設定
  loadWorkItems();
  renderInterruptRecords();

  // 今日の日付を設定
  const today = new Date().toISOString().split('T')[0];
  container.querySelector('#work-date').value = today;

  // イベントリスナー
  container.querySelector('#start-time').addEventListener('change', calculateWorkTime);
  container.querySelector('#end-time').addEventListener('change', calculateWorkTime);
  container.querySelector('#break-time').addEventListener('input', calculateWorkTime);
  container.querySelector('#work-details').addEventListener('input', updateCharCount);

  // 登録ボタン
  container.querySelector('#btn-save').addEventListener('click', async () => {
    if (!validateForm()) return;

    const workData = {
      作業員ID: currentUser.id,
      作業日: new Date(container.querySelector('#work-date').value).toISOString(),
      作業開始時刻: new Date(`${container.querySelector('#work-date').value}T${container.querySelector('#start-time').value}`).toISOString(),
      作業終了時刻: new Date(`${container.querySelector('#work-date').value}T${container.querySelector('#end-time').value}`).toISOString(),
      プロジェクト名: container.querySelector('#work-item option:checked').textContent,
      作業場所: container.querySelector('#work-location').value,
      作業種別: container.querySelector('#work-item option:checked').textContent,
      作業内容: container.querySelector('#work-details').value,
      進捗状況: container.querySelector('#progress-status').value,
      承認状態: '未承認',
      作成者ID: currentUser.id
    };

    const saved = await window.aivicApi.save(1, workData);
    if (saved) {
      // 中断記録も保存
      for (const interrupt of interruptRecords) {
        interrupt.作業記録ID = saved.作業記録ID;
        await window.aivicApi.save(2, interrupt);
      }

      alert('工数記録が正常に登録されました');
      container.querySelector('#work-entry-form').reset();
      container.querySelector('#worker-name').value = currentUser.name;
      container.querySelector('#work-date').value = today;
      interruptRecords = [];
      renderInterruptRecords();
    }
  });

  // 中断ボタン
  container.querySelector('#btn-interrupt').addEventListener('click', () => {
    const interruptForm = container.querySelector('#interrupt-form');
    if (interruptForm.style.display === 'none') {
      interruptForm.style.display = 'grid';
      container.querySelector('#progress-status').value = '中断';
    } else {
      interruptForm.style.display = 'none';
    }
  });

  // 中断記録追加
  container.querySelector('#btn-add-interrupt').addEventListener('click', () => {
    const reason = container.querySelector('#interrupt-reason').value;
    const startTime = container.querySelector('#interrupt-start').value;
    const endTime = container.querySelector('#interrupt-end').value;

    if (!reason || !startTime) {
      showError('中断理由と開始時刻を入力してください');
      return;
    }

    const interruptRecord = {
      中断記録ID: `interrupt-${Date.now()}`,
      中断開始日時: new Date(`${container.querySelector('#work-date').value}T${startTime}`).toISOString(),
      中断終了日時: endTime ? new Date(`${container.querySelector('#work-date').value}T${endTime}`).toISOString() : null,
      中断理由区分: reason,
      対応状況: '記録済み',
      記録者ID: currentUser.id
    };

    interruptRecords.push(interruptRecord);
    renderInterruptRecords();

    // フォームクリア
    container.querySelector('#interrupt-reason').value = '';
    container.querySelector('#interrupt-start').value = '';
    container.querySelector('#interrupt-end').value = '';
  });

  // 作業終了ボタン
  container.querySelector('#btn-complete').addEventListener('click', () => {
    window.showScreen("scr-1778907199709");
  });

  // 中断記録削除
  container.addEventListener('click', (e) => {
    const deleteBtn = e.target.closest('.delete-interrupt-btn');
    if (deleteBtn) {
      const index = parseInt(deleteBtn.dataset.index);
      if (confirm('この中断記録を削除しますか？')) {
        interruptRecords.splice(index, 1);
        renderInterruptRecords();
      }
    }
  });
}

function(container, apiUrl, tables) {
  let workRecords = [];
  let workItems = [];
  let breakRecords = [];
  let selectedRecord = null;

  // エラーメッセージ表示
  function showError(message) {
    const errorDiv = container.querySelector('#error-messages');
    errorDiv.innerHTML = `<div style="padding: 8px 12px; background: rgba(220, 38, 38, 0.1); border: 1px solid rgba(220, 38, 38, 0.3); border-radius: 6px; color: #fca5a5; font-size: 13px; margin-bottom: 8px;">${message}</div>`;
    setTimeout(() => errorDiv.innerHTML = '', 5000);
  }

  // 成功メッセージ表示
  function showSuccess(message) {
    const errorDiv = container.querySelector('#error-messages');
    errorDiv.innerHTML = `<div style="padding: 8px 12px; background: rgba(34, 197, 94, 0.1); border: 1px solid rgba(34, 197, 94, 0.3); border-radius: 6px; color: #86efac; font-size: 13px; margin-bottom: 8px;">${message}</div>`;
    setTimeout(() => errorDiv.innerHTML = '', 3000);
  }

  // 異常値警告表示
  function showAnomalyWarnings(warnings) {
    const warningDiv = container.querySelector('#anomaly-warnings');
    if (warnings.length === 0) {
      warningDiv.innerHTML = '';
      return;
    }

    const warningHtml = warnings.map(warning => 
      `<div style="padding: 6px 10px; background: rgba(251, 146, 60, 0.1); border: 1px solid rgba(251, 146, 60, 0.3); border-radius: 4px; color: #fed7aa; font-size: 12px; margin-bottom: 4px;">${warning}</div>`
    ).join('');
    warningDiv.innerHTML = warningHtml;
  }

  // 時刻計算
  function calculateTimes() {
    const startTime = container.querySelector('#start-time').value;
    const endTime = container.querySelector('#end-time').value;
    const breakTime = container.querySelector('#break-time').value;

    if (!startTime || !endTime) {
      container.querySelector('#actual-work-time').textContent = '-';
      container.querySelector('#break-duration').textContent = '-';
      return;
    }

    const start = new Date(`2000-01-01T${startTime}`);
    const end = new Date(`2000-01-01T${endTime}`);

    if (end <= start) {
      container.querySelector('#actual-work-time').textContent = '-';
      container.querySelector('#break-duration').textContent = '-';
      return;
    }

    const totalMinutes = (end - start) / (1000 * 60);
    let breakMinutes = 0;

    if (breakTime) {
      const breakStart = new Date(`2000-01-01T${breakTime}`);
      if (breakStart >= start && breakStart <= end) {
        breakMinutes = 60; // 仮に1時間の中断とする
        container.querySelector('#break-duration').textContent = `${Math.floor(breakMinutes / 60)}時間${breakMinutes % 60}分`;
      }
    } else {
      container.querySelector('#break-duration').textContent = '-';
    }

    const actualMinutes = totalMinutes - breakMinutes;
    const hours = Math.floor(actualMinutes / 60);
    const minutes = actualMinutes % 60;
    container.querySelector('#actual-work-time').textContent = `${hours}時間${minutes}分`;
  }

  // バリデーション
  function validateForm() {
    const warnings = [];
    const startTime = container.querySelector('#start-time').value;
    const endTime = container.querySelector('#end-time').value;
    const workDate = container.querySelector('#work-date').value;
    const breakTime = container.querySelector('#break-time').value;

    // 日付チェック
    if (workDate) {
      const date = new Date(workDate);
      const today = new Date();
      if (date > today) {
        warnings.push('作業日付が未来の日付です');
      }
      if (date.getFullYear() < 1900 || date.getFullYear() > 2099) {
        warnings.push('作業日付が有効範囲外です（1900-2099年）');
      }
    }

    // 時刻チェック
    if (startTime && endTime) {
      const start = new Date(`2000-01-01T${startTime}`);
      const end = new Date(`2000-01-01T${endTime}`);

      if (end <= start) {
        warnings.push('開始時刻は終了時刻より前の時刻を入力してください');
      }

      const totalHours = (end - start) / (1000 * 60 * 60);
      if (totalHours > 16) {
        warnings.push('作業時間が16時間を超えています。異常な長時間作業の可能性があります');
      }
    }

    // 中断時刻チェック
    if (breakTime && startTime && endTime) {
      const start = new Date(`2000-01-01T${startTime}`);
      const end = new Date(`2000-01-01T${endTime}`);
      const breakStart = new Date(`2000-01-01T${breakTime}`);

      if (breakStart < start || breakStart > end) {
        warnings.push('中断時刻が作業時間外です');
      }
    }

    showAnomalyWarnings(warnings);
    return warnings.length === 0;
  }

  // 修正対象記録選択時の処理
  function loadRecordData(recordId) {
    const record = workRecords.find(r => r.作業記録ID === recordId);
    if (!record) return;

    selectedRecord = record;

    // フォーム表示
    container.querySelector('#correction-form').style.display = 'block';

    // データ設定
    const workDate = new Date(record.作業日);
    container.querySelector('#work-date').value = workDate.toISOString().split('T')[0];

    const startTime = new Date(record.作業開始時刻);
    container.querySelector('#start-time').value = startTime.toTimeString().slice(0, 5);

    if (record.作業終了時刻) {
      const endTime = new Date(record.作業終了時刻);
      container.querySelector('#end-time').value = endTime.toTimeString().slice(0, 5);
    }

    // 作業項目設定
    const workItemSelect = container.querySelector('#work-item');
    const matchingItem = workItems.find(item => 
      item.作業項目名 === record.作業種別 || item.作業項目コード === record.作業種別
    );
    if (matchingItem) {
      workItemSelect.value = matchingItem.作業項目ID;
    }

    // 中断記録があれば設定
    const breakRecord = breakRecords.find(br => br.作業記録ID === recordId);
    if (breakRecord) {
      if (breakRecord.中断開始日時) {
        const breakTime = new Date(breakRecord.中断開始日時);
        container.querySelector('#break-time').value = breakTime.toTimeString().slice(0, 5);
      }
      container.querySelector('#break-reason').value = breakRecord.中断理由区分 || '';
    }

    // 修正前データ表示
    const originalDataDiv = container.querySelector('#original-data');
    originalDataDiv.innerHTML = `
      <div><strong>作業日:</strong> ${workDate.toLocaleDateString('ja-JP')}</div>
      <div><strong>作業時間:</strong> ${startTime.toTimeString().slice(0, 5)} - ${record.作業終了時刻? new Date(record.作業終了時刻).toTimeString().slice(0, 5) : '未終了'}</div>
      <div><strong>作業項目:</strong> ${record.作業種別}</div>
      <div><strong>作業内容:</strong> ${record.作業内容}</div>
      <div><strong>進捗状況:</strong> ${record.進捗状況}</div>
    `;

    calculateTimes();
  }

  // 初期データ読み込み
  async function loadInitialData() {
    try {
      // 作業記録取得
      workRecords = await window.aivicApi.list(1) || tables[1]?.records || [];

      // 作業項目マスタ取得
      workItems = await window.aivicApi.list(3) || tables[3]?.records || [];

      // 中断記録取得
      breakRecords = await window.aivicApi.list(2) || tables[2]?.records || [];

      // 修正対象記録ドロップダウン設定
      const targetSelect = container.querySelector('#target-record');
      targetSelect.innerHTML = '<option value="">記録を選択してください</option>';

      workRecords.forEach(record => {
        const workDate = new Date(record.作業日).toLocaleDateString('ja-JP');
        const option = document.createElement('option');
        option.value = record.作業記録ID;
        option.textContent = `${workDate} - ${record.作業種別} (${record.進捗状況})`;
        targetSelect.appendChild(option);
      });

      // 作業項目ドロップダウン設定
      const workItemSelect = container.querySelector('#work-item');
      workItemSelect.innerHTML = '<option value="">作業項目を選択</option>';

      workItems
        .filter(item => item.有効フラグ)
        .sort((a, b) => (a.表示順序 || 0) - (b.表示順序 || 0))
        .forEach(item => {
          const option = document.createElement('option');
          option.value = item.作業項目ID;
          option.textContent = `${item.作業項目コード} - ${item.作業項目名}`;
          workItemSelect.appendChild(option);
        });

    } catch (error) {
      console.error('データ読み込みエラー:', error);
      showError('データの読み込みに失敗しました');
    }
  }

  // イベントリスナー設定
  container.querySelector('#target-record').addEventListener('change', (e) => {
    if (e.target.value) {
      loadRecordData(e.target.value);
    } else {
      container.querySelector('#correction-form').style.display = 'none';
      selectedRecord = null;
    }
  });

  // 修正理由文字数カウント
  container.querySelector('#correction-reason').addEventListener('input', (e) => {
    const count = e.target.value.length;
    container.querySelector('#reason-count').textContent = count;
  });

  // 時刻変更時の計算
  ['#start-time', '#end-time', '#break-time'].forEach(selector => {
    container.querySelector(selector).addEventListener('change', () => {
      calculateTimes();
      validateForm();
    });
  });

  // 日付変更時のバリデーション
  container.querySelector('#work-date').addEventListener('change', validateForm);

  // 保存ボタン
  container.querySelector('#btn-save').addEventListener('click', async () => {
    if (!selectedRecord) {
      showError('修正対象の記録が選択されていません');
      return;
    }

    const reason = container.querySelector('#correction-reason').value.trim();
    if (!reason) {
      showError('修正理由を入力してください');
      return;
    }

    if (!validateForm()) {
      showError('入力内容に問題があります。警告メッセージを確認してください');
      return;
    }

    try {
      const workDate = container.querySelector('#work-date').value;
      const startTime = container.querySelector('#start-time').value;
      const endTime = container.querySelector('#end-time').value;
      const workItemId = container.querySelector('#work-item').value;
      const breakTime = container.querySelector('#break-time').value;
      const breakReason = container.querySelector('#break-reason').value;

      // 作業記録更新
      const updateData = {
        作業日: new Date(`${workDate}T00:00:00`).toISOString(),
        作業開始時刻: new Date(`${workDate}T${startTime}:00`).toISOString(),
        作業終了時刻: endTime ? new Date(`${workDate}T${endTime}:00`).toISOString() : null,
        更新日時: new Date().toISOString()
      };

      if (workItemId) {
        const workItem = workItems.find(item => item.作業項目ID === workItemId);
        if (workItem) {
          updateData.作業種別 = workItem.作業項目名;
        }
      }

      // 作業時間計算
      if (startTime && endTime) {
        const start = new Date(`${workDate}T${startTime}:00`);
        const end = new Date(`${workDate}T${endTime}:00`);
        updateData.作業時間 = Math.floor((end - start) / (1000 * 60));
      }

      await window.aivicApi.update(1, selectedRecord.作業記録ID, updateData);

      // 中断記録の処理
      const existingBreakRecord = breakRecords.find(br => br.作業記録ID === selectedRecord.作業記録ID);

      if (breakTime && breakReason) {
        const breakData = {
          作業記録ID: selectedRecord.作業記録ID,
          中断開始日時: new Date(`${workDate}T${breakTime}:00`).toISOString(),
          中断理由区分: breakReason,
          中断時間: 60, // 仮に1時間
          対応状況: '対応中',
          記録者ID: selectedRecord.作業員ID,
          更新日時: new Date().toISOString()
        };

        if (existingBreakRecord) {
          await window.aivicApi.update(2, existingBreakRecord.中断記録ID, breakData);
        } else {
          breakData.中断記録ID = crypto.randomUUID();
          breakData.作成日時 = new Date().toISOString();
          await window.aivicApi.save(2, breakData);
        }
      }

      showSuccess('修正が正常に保存されました');

      // フォームリセット
      container.querySelector('#target-record').value = '';
      container.querySelector('#correction-form').style.display = 'none';
      container.querySelector('#correction-reason').value = '';
      container.querySelector('#reason-count').textContent = '0';
      selectedRecord = null;

      // データ再読み込み
      await loadInitialData();

    } catch (error) {
      console.error('保存エラー:', error);
      showError('修正の保存に失敗しました');
    }
  });

  // キャンセルボタン
  container.querySelector('#btn-cancel').addEventListener('click', () => {
    window.showScreen('scr-1778907145716'); // 作業履歴一覧画面
  });

  // 初期化
  loadInitialData();
}

function(container, apiUrl, tables) {
