  const contentCounter = container.querySelector("#content-counter");

  emergencyContentTextarea.addEventListener("input", () => {
    const length = emergencyContentTextarea.value.length;
    contentCounter.textContent = length;

    if (length > 1000) {
      contentCounter.style.color = "#dc2626";
      emergencyContentTextarea.style.borderColor = "#dc2626";
    } else {
      contentCounter.style.color = "var(--text-muted)";
      emergencyContentTextarea.style.borderColor = "rgba(255,255,255,0.18)";
    }
  });

  // 写真アップロード処理
  const photoUploadArea = container.querySelector("#photo-upload-area");
  const photoInput = container.querySelector("#photo-input");
  const photoPreview = container.querySelector("#photo-preview");
  let uploadedFiles = [];

  photoUploadArea.addEventListener("click", () => {
    photoInput.click();
  });

  photoUploadArea.addEventListener("dragover", (e) => {
    e.preventDefault();
    photoUploadArea.style.borderColor = "var(--primary)";
  });

  photoUploadArea.addEventListener("dragleave", () => {
    photoUploadArea.style.borderColor = "rgba(255,255,255,0.18)";
  });

  photoUploadArea.addEventListener("drop", (e) => {
    e.preventDefault();
    photoUploadArea.style.borderColor = "rgba(255,255,255,0.18)";
    handleFiles(e.dataTransfer.files);
  });

  photoInput.addEventListener("change", (e) => {
    handleFiles(e.target.files);
  });

  function handleFiles(files) {
    const maxFiles = 5;
    const maxSize = 10 * 1024 * 1024; // 10MB
    const allowedTypes = ['image/jpeg', 'image/png', 'image/gif'];

    Array.from(files).forEach(file => {
      if (uploadedFiles.length >= maxFiles) {
        showError(`画像は最大${maxFiles}枚まで添付できます`);
        return;
      }

      if (file.size > maxSize) {
        showError(`ファイルサイズは10MB以下にしてください: ${file.name}`);
        return;
      }

      if (!allowedTypes.includes(file.type)) {
        showError(`サポートされていないファイル形式です: ${file.name}`);
        return;
      }

      uploadedFiles.push(file);
      displayPhotoPreview(file);
    });
  }

  function displayPhotoPreview(file) {
    const reader = new FileReader();
    reader.onload = (e) => {
      const previewItem = document.createElement("div");
      previewItem.style.cssText = "position: relative; display: inline-block;";

      previewItem.innerHTML = `
        <img src="${e.target.result}" style="width: 80px; height: 80px; object-fit: cover; border-radius: 4px; border: 1px solid rgba(255,255,255,0.18);" />
        <button type="button" class="remove-photo" data-filename="${file.name}" style="position: absolute; top: -6px; right: -6px; width: 20px; height: 20px; border-radius: 50%; background: #dc2626; color: #fff; border: none; font-size: 12px; cursor: pointer; display: flex; align-items: center; justify-content: center;">×</button>
      `;

      photoPreview.appendChild(previewItem);
    };
    reader.readAsDataURL(file);
  }

  // 写真削除処理
  photoPreview.addEventListener("click", (e) => {
    if (e.target.classList.contains("remove-photo")) {
      const filename = e.target.dataset.filename;
      uploadedFiles = uploadedFiles.filter(f => f.name !== filename);
      e.target.closest("div").remove();
    }
  });

  // バリデーション関数
  function validateForm() {
    const errors = [];

    const urgency = selectedUrgencyInput.value;
    if (!urgency) {
      errors.push("緊急度を選択してください");
    }

    const reportType = container.querySelector("#report-type").value;
    if (!reportType) {
      errors.push("報告種別を選択してください");
    }

    const occurrenceDateTime = container.querySelector("#occurrence-datetime").value;
    if (!occurrenceDateTime) {
      errors.push("発生日時を入力してください");
    } else {
      const selectedDate = new Date(occurrenceDateTime);
      const now = new Date();
      if (selectedDate > now) {
        errors.push("発生日時に未来の日付は入力できません");
      }
    }

    const occurrenceLocation = container.querySelector("#occurrence-location").value.trim();
    if (!occurrenceLocation) {
      errors.push("発生場所を入力してください");
    }

    const emergencyContent = emergencyContentTextarea.value.trim();
    if (!emergencyContent) {
      errors.push("緊急事態内容を入力してください");
    } else if (emergencyContent.length > 1000) {
      errors.push("緊急事態内容は1000文字以内で入力してください");
    }

    const contactPhone = container.querySelector("#contact-phone").value.trim();
    if (!contactPhone) {
      errors.push("連絡先電話番号を入力してください");
    } else {
      const phonePattern = /^(\d{2,4}-\d{2,4}-\d{4}|\d{10,11})$/;
      if (!phonePattern.test(contactPhone.replace(/[^\d-]/g, ''))) {
        errors.push("正しい電話番号の形式で入力してください");
      }
    }

    return errors;
  }

  // エラー表示関数
  function showError(message) {
    const errorDiv = container.querySelector("#error-messages");
    const errorText = container.querySelector("#error-text");
    errorText.textContent = message;
    errorDiv.classList.remove("hidden");

    setTimeout(() => {
      errorDiv.classList.add("hidden");
    }, 5000);
  }

  // 成功メッセージ表示関数
  function showSuccess() {
    const successDiv = container.querySelector("#success-message");
    successDiv.classList.remove("hidden");

    setTimeout(() => {
      successDiv.classList.add("hidden");
    }, 3000);
  }

  // フォーム送信処理
  const form = container.querySelector("#emergency-form");
  form.addEventListener("submit", async (e) => {
    e.preventDefault();

    const errors = validateForm();
    if (errors.length > 0) {
      showError(errors.join("、"));
      return;
    }

    const formData = {
      緊急度: selectedUrgencyInput.value,
      報告種別: container.querySelector("#report-type").value,
      発生日時: container.querySelector("#occurrence-datetime").value,
      発生場所: container.querySelector("#occurrence-location").value,
      作業項目ID: container.querySelector("#work-item").value || null,
      緊急事態内容: emergencyContentTextarea.value,
      報告者ID: currentUser.id,
      報告者名: reporterNameInput.value,
      連絡先電話番号: container.querySelector("#contact-phone").value,
      添付ファイル数: uploadedFiles.length,
      報告日時: new Date().toISOString(),
      状態: "送信済み"
    };

    try {
      // 緊急報告データを保存（異常値検出ログテーブルを使用）
      const saved = await window.aivicApi.save(4, {
        検出対象テーブル: "緊急報告",
        検出対象レコードID: crypto.randomUUID(),
        ユーザーID: currentUser.id,
        異常値種別: formData.報告種別,
        検出項目: "緊急報告",
        検出値: formData.緊急事態内容,
        閾値: formData.緊急度,
        重要度: formData.緊急度,
        確認状況: "未確認",
        通知送信フラグ: true,
        検出日時: formData.報告日時,
        作成日時: formData.報告日時,
        更新日時: formData.報告日時
      });

      if (saved) {
        showSuccess();
        // フォームをリセット
        form.reset();
        selectedUrgencyInput.value = "";
        urgencyButtons.forEach(b => {
          b.style.background = "transparent";
          b.style.borderColor = "rgba(255,255,255,0.18)";
          b.style.color = "var(--text)";
        });
        uploadedFiles = [];
        photoPreview.innerHTML = "";
        contentCounter.textContent = "0";
        reporterNameInput.value = currentUser.name;

        // 3秒後に工数記録画面に遷移
        setTimeout(() => {
          window.showScreen("scr-1778907133295");
        }, 3000);
      } else {
        showError("報告の送信に失敗しました。再度お試しください。");
      }
    } catch (error) {
      console.error("送信エラー:", error);
      showError("報告の送信中にエラーが発生しました。");
    }
  });

  // 下書き保存処理
  const draftButton = container.querySelector("#btn-draft");
  draftButton.addEventListener("click", () => {
    const draftData = {
      緊急度: selectedUrgencyInput.value,
      報告種別: container.querySelector("#report-type").value,
      発生日時: container.querySelector("#occurrence-datetime").value,
      発生場所: container.querySelector("#occurrence-location").value,
      作業項目ID: container.querySelector("#work-item").value,
      緊急事態内容: emergencyContentTextarea.value,
      連絡先電話番号: container.querySelector("#contact-phone").value,
      添付ファイル数: uploadedFiles.length
    };

    localStorage.setItem("emergencyReportDraft", JSON.stringify(draftData));
    showSuccess();

    setTimeout(() => {
      const successDiv = container.querySelector("#success-message");
      successDiv.querySelector("div").textContent = "下書きが保存されました";
      successDiv.classList.remove("hidden");
      setTimeout(() => {
        successDiv.classList.add("hidden");
        successDiv.querySelector("div").textContent = "緊急報告が正常に送信されました";
      }, 2000);
    }, 100);
  });

  // 戻るボタン処理
  const backButton = container.querySelector("#btn-back");
  backButton.addEventListener("click", () => {
    window.showScreen("scr-1778907133295");
  });

  // 下書きデータの復元
  function loadDraft() {
    const draftData = localStorage.getItem("emergencyReportDraft");
    if (draftData) {
      try {
        const data = JSON.parse(draftData);

        if (data.緊急度) {
          selectedUrgencyInput.value = data.緊急度;
          const targetBtn = container.querySelector(`[data-urgency="${data.緊急度}"]`);
          if (targetBtn) {
            targetBtn.style.background = "var(--primary)";
            targetBtn.style.borderColor = "var(--primary)";
            targetBtn.style.color = "#fff";
          }
        }

        if (data.報告種別) container.querySelector("#report-type").value = data.報告種別;
        if (data.発生日時) container.querySelector("#occurrence-datetime").value = data.発生日時;
        if (data.発生場所) container.querySelector("#occurrence-location").value = data.発生場所;
        if (data.作業項目ID) container.querySelector("#work-item").value = data.作業項目ID;
        if (data.緊急事態内容) {
          emergencyContentTextarea.value = data.緊急事態内容;
          contentCounter.textContent = data.緊急事態内容.length;
        }
        if (data.連絡先電話番号) container.querySelector("#contact-phone").value = data.連絡先電話番号;
      } catch (error) {
        console.error("下書きデータの復元に失敗しました:", error);
      }
    }
  }

  // 初期化処理
  loadWorkItems();
  loadDraft();

  // 発生日時のデフォルト値を現在時刻に設定
  const now = new Date();
  const localDateTime = new Date(now.getTime() - now.getTimezoneOffset() * 60000).toISOString().slice(0, 16);
  container.querySelector("#occurrence-datetime").value = localDateTime;
}

function(container, apiUrl, tables) {
  let workRecords = [];
  let workItems = [];
  let selectedRecord = null;
  let originalRecord = null;

  // 初期データ読み込み
  async function loadData() {
    try {
      workRecords = await window.aivicApi.list(1) || tables[1]?.records || [];
      workItems = await window.aivicApi.list(3) || tables[3]?.records || [];

      populateWorkRecordSelect();
      populateWorkItemSelect();
    } catch (error) {
      console.error('データ読み込みエラー:', error);
      workRecords = tables[1]?.records || [];
      workItems = tables[3]?.records || [];
      populateWorkRecordSelect();
      populateWorkItemSelect();
    }
  }

  function populateWorkRecordSelect() {
    const select = container.querySelector('#work-record-select');
    select.innerHTML = '<option value="">選択してください</option>';

    workRecords.forEach(record => {
      const option = document.createElement('option');
      option.value = record.id;
      const workDate = new Date(record.作業日).toLocaleDateString('ja-JP');
      option.textContent = `${workDate} - ${record.プロジェクト名} (${record.作業種別})`;
      select.appendChild(option);
    });
  }

  function populateWorkItemSelect() {
    const select = container.querySelector('#work-item-select');
    select.innerHTML = '<option value="">選択してください</option>';

    workItems
      .filter(item => item.有効フラグ)
      .sort((a, b) => (a.表示順序 || 0) - (b.表示順序 || 0))
      .forEach(item => {
        const option = document.createElement('option');
        option.value = item.id;
        option.textContent = `${item.作業項目コード} - ${item.作業項目名}`;
        select.appendChild(option);
      });
  }

  function calculateWorkTime() {
    const startTime = container.querySelector('#start-time').value;
    const endTime = container.querySelector('#end-time').value;
    const breakTime = parseInt(container.querySelector('#break-time').value) || 0;

    if (!startTime || !endTime) {
      container.querySelector('#total-work-time').value = '';
      container.querySelector('#net-work-time').value = '';
      return;
    }

    const start = new Date(`2000-01-01T${startTime}`);
    let end = new Date(`2000-01-01T${endTime}`);

    // 24時間跨ぎの処理
    if (end <= start) {
      end = new Date(`2000-01-02T${endTime}`);
    }

    const totalMinutes = (end - start) / (1000 * 60);
    const netMinutes = Math.max(0, totalMinutes - breakTime);

    const totalHours = Math.floor(totalMinutes / 60);
    const totalMins = totalMinutes % 60;
    const netHours = Math.floor(netMinutes / 60);
    const netMins = netMinutes % 60;

    container.querySelector('#total-work-time').value = `${totalHours}時間${totalMins}分`;
    container.querySelector('#net-work-time').value = `${netHours}時間${netMins}分`;
  }

  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    errorDiv.textContent = message;
    errorDiv.style.display = 'block';
    container.querySelector('#warning-message').style.display = 'none';
  }

  function showWarning(message) {
    const warningDiv = container.querySelector('#warning-message');
    warningDiv.textContent = message;
    warningDiv.style.display = 'block';
    container.querySelector('#error-message').style.display = 'none';
  }

  function hideMessages() {
    container.querySelector('#error-message').style.display = 'none';
    container.querySelector('#warning-message').style.display = 'none';
  }

  function validateForm() {
    const recordId = container.querySelector('#work-record-select').value;
    const startTime = container.querySelector('#start-time').value;
    const endTime = container.querySelector('#end-time').value;
    const breakTime = parseInt(container.querySelector('#break-time').value) || 0;
    const correctionReason = container.querySelector('#correction-reason').value.trim();

    if (!recordId) {
      showError('修正対象の作業記録を選択してください');
      return false;
    }

    if (!startTime || !endTime) {
      showError('作業開始時刻と終了時刻を入力してください');
      return false;
    }

    if (!correctionReason) {
      showError('修正理由を入力してください');
      return false;
    }

    const start = new Date(`2000-01-01T${startTime}`);
    let end = new Date(`2000-01-01T${endTime}`);

    if (end <= start) {
      end = new Date(`2000-01-02T${endTime}`);
    }

    if (start.getTime() === end.getTime()) {
      showError('作業時間が0分です。開始時刻と終了時刻を確認してください。');
      return false;
    }

    const totalMinutes = (end - start) / (1000 * 60);

    if (breakTime > totalMinutes) {
      showError('中断時間が作業時間を超過しています');
      return false;
    }

    // 異常な作業時間の警告（12時間以上）
    if (totalMinutes > 720) {
      showWarning('作業時間が12時間を超えています。確認してください。');
    }

    return true;
  }

  // 作業記録選択時の処理
  container.querySelector('#work-record-select').addEventListener('change', function() {
    const recordId = this.value;
    if (!recordId) {
      selectedRecord = null;
      originalRecord = null;
      // フォームクリア
      container.querySelector('#work-date').value = '';
      container.querySelector('#start-time').value = '';
      container.querySelector('#end-time').value = '';
      container.querySelector('#break-time').value = '';
      container.querySelector('#work-item-select').value = '';
      container.querySelector('#work-details').value = '';
      container.querySelector('#correction-reason').value = '';
      calculateWorkTime();
      hideMessages();
      return;
    }

    selectedRecord = workRecords.find(r => r.id === recordId);
    originalRecord = { ...selectedRecord }; // 元データ保存

    if (selectedRecord) {
      // フォームに既存データを設定
      const workDate = new Date(selectedRecord.作業日).toLocaleDateString('ja-JP');
      container.querySelector('#work-date').value = workDate;

      const startTime = new Date(selectedRecord.作業開始時刻);
      const endTime = selectedRecord.作業終了時刻? new Date(selectedRecord.作業終了時刻) : null;

      container.querySelector('#start-time').value = startTime.toTimeString().slice(0, 5);
      if (endTime) {
        container.querySelector('#end-time').value = endTime.toTimeString().slice(0, 5);
      }

      container.querySelector('#work-details').value = selectedRecord.作業内容 || '';

      // 中断時間の計算（中断記録から取得）
      const breakRecords = tables[2]?.records?.filter(br => br.作業記録ID === recordId) || [];
      const totalBreakTime = breakRecords.reduce((sum, br) => sum + (br.中断時間 || 0), 0);
      container.querySelector('#break-time').value = totalBreakTime;

      calculateWorkTime();
      hideMessages();
    }
  });

  // 時刻変更時の自動計算
  container.querySelector('#start-time').addEventListener('change', calculateWorkTime);
  container.querySelector('#end-time').addEventListener('change', calculateWorkTime);
  container.querySelector('#break-time').addEventListener('input', calculateWorkTime);

  // 保存ボタン
  container.querySelector('#btn-save').addEventListener('click', async function() {
    if (!validateForm()) return;

    try {
      const recordId = container.querySelector('#work-record-select').value;
      const startTime = container.querySelector('#start-time').value;
      const endTime = container.querySelector('#end-time').value;
      const breakTime = parseInt(container.querySelector('#break-time').value) || 0;
      const workItemId = container.querySelector('#work-item-select').value;
      const workDetails = container.querySelector('#work-details').value.trim();
      const correctionReason = container.querySelector('#correction-reason').value.trim();

      // 作業時間の計算
      const start = new Date(`2000-01-01T${startTime}`);
      let end = new Date(`2000-01-01T${endTime}`);
      if (end <= start) {
        end = new Date(`2000-01-02T${endTime}`);
      }
      const totalMinutes = (end - start) / (1000 * 60);
      const netMinutes = Math.max(0, totalMinutes - breakTime);

      // 作業記録の更新
      const updateData = {
        作業開始時刻: new Date(selectedRecord.作業日.split('T')[0] + 'T' + startTime).toISOString(),
        作業終了時刻: new Date(selectedRecord.作業日.split('T')[0] + 'T' + endTime).toISOString(),
        作業時間: Math.round(netMinutes),
        作業内容: workDetails,
        更新日時: new Date().toISOString()
      };

      const result = await window.aivicApi.update(1, recordId, updateData);

      if (result) {
        // 修正完了後、工数記録確認画面に遷移
        window.showScreen("scr-1778907367889");
      } else {
        showError('修正の保存に失敗しました');
      }
    } catch (error) {
      console.error('保存エラー:', error);
      showError('修正の保存中にエラーが発生しました');
    }
  });

  // 元データ参照ボタン
  container.querySelector('#btn-view-original').addEventListener('click', function() {
    if (!originalRecord) {
      showError('修正対象の作業記録を選択してください');
      return;
    }

    const modal = container.querySelector('#original-data-modal');
    const content = container.querySelector('#original-data-content');

    const workDate = new Date(originalRecord.作業日).toLocaleDateString('ja-JP');
    const startTime = new Date(originalRecord.作業開始時刻).toLocaleTimeString('ja-JP', { hour: '2-digit', minute: '2-digit' });
    const endTime = originalRecord.作業終了時刻 ? new Date(originalRecord.作業終了時刻).toLocaleTimeString('ja-JP', { hour: '2-digit', minute: '2-digit' }) : '未設定';

    content.innerHTML = `
      <div style="margin-bottom: 8px;"><strong>作業日:</strong> ${workDate}</div>
      <div style="margin-bottom: 8px;"><strong>開始時刻:</strong> ${startTime}</div>
      <div style="margin-bottom: 8px;"><strong>終了時刻:</strong> ${endTime}</div>
      <div style="margin-bottom: 8px;"><strong>作業時間:</strong> ${originalRecord.作業時間 || 0}分</div>
      <div style="margin-bottom: 8px;"><strong>プロジェクト:</strong> ${originalRecord.プロジェクト名 || ''}</div>
      <div style="margin-bottom: 8px;"><strong>作業場所:</strong> ${originalRecord.作業場所 || ''}</div>
      <div style="margin-bottom: 8px;"><strong>作業種別:</strong> ${originalRecord.作業種別 || ''}</div>
      <div style="margin-bottom: 8px;"><strong>作業内容:</strong> ${originalRecord.作業内容 || ''}</div>
      <div style="margin-bottom: 8px;"><strong>進捗状況:</strong> ${originalRecord.進捗状況 || ''}</div>
    `;

    modal.style.display = 'block';
  });

  // モーダル閉じるボタン
  container.querySelector('#btn-close-modal').addEventListener('click', function() {
    container.querySelector('#original-data-modal').style.display = 'none';
  });

  // モーダル背景クリックで閉じる
  container.querySelector('#original-data-modal').addEventListener('click', function(e) {
    if (e.target === this) {
      this.style.display = 'none';
    }
  });

  // 初期化
  loadData();
}

function(container, apiUrl, tables) {
  let workRecords = [];
  let users = [];
  let workItems = [];
  let interruptionRecords = [];
  let anomalyLogs = [];

  // テーブルインデックス定義
  const TABLE_USERS = 0;
  const TABLE_WORK_RECORDS = 1;
  const TABLE_INTERRUPTIONS = 2;
  const TABLE_WORK_ITEMS = 3;
  const TABLE_ANOMALY_LOGS = 4;

  // 初期データ設定
  users = tables[TABLE_USERS]?.records || [];
  workRecords = tables[TABLE_WORK_RECORDS]?.records || [];
  interruptionRecords = tables[TABLE_INTERRUPTIONS]?.records || [];
  workItems = tables[TABLE_WORK_ITEMS]?.records || [];
  anomalyLogs = tables[TABLE_ANOMALY_LOGS]?.records || [];

  // 作業員リスト描画
  function renderWorkerList() {
    const workerListEl = container.querySelector('#worker-list');
    workerListEl.innerHTML = users.map(user => `
      <label style="display: block; font-size: 12px; margin-bottom: 2px;">
        <input type="checkbox" class="worker-checkbox" value="${user.ユーザーID}" style="accent-color: var(--primary); margin-right: 6px;">
        ${user.氏名 || user.ユーザー名 || ''}
      </label>
    `).join('');
  }

  // 作業項目リスト描画
  function renderWorkItemList() {
    const itemListEl = container.querySelector('#item-list');
    itemListEl.innerHTML = workItems.map(item => `
      <label style="display: block; font-size: 12px; margin-bottom: 2px;">
        <input type="checkbox" class="item-checkbox" value="${item.作業項目ID}" style="accent-color: var(--primary); margin-right: 6px;">
        ${item.作業項目名 || ''}
      </label>
    `).join('');
  }

  // 作業場所選択肢描画
  function renderWorkLocations() {
    const locationEl = container.querySelector('#work-location');
    const locations = [...new Set(workRecords.map(r => r.作業場所).filter(Boolean))];
    locationEl.innerHTML = '<option value="">全て</option>' + 
      locations.map(loc => `<option value="${loc}">${loc}</option>`).join('');
  }

  // エラー表示
  function showError(message) {
    const errorEl = container.querySelector('#error-message');
    errorEl.textContent = message;
    errorEl.style.display = 'block';
    setTimeout(() => {
      errorEl.style.display = 'none';
    }, 5000);
  }

  // 条件バリデーション
  function validateConditions() {
    const startDate = container.querySelector('#start-date').value;
    const endDate = container.querySelector('#end-date').value;
    const outputFormat = container.querySelector('#output-format').value;

    if (!startDate || !endDate) {
      showError('抽出期間を指定してください');
      return false;
    }

    if (new Date(startDate) > new Date(endDate)) {
      showError('開始日は終了日より前の日付を入力してください');
      return false;
    }

    const selectedWorkers = Array.from(container.querySelectorAll('.worker-checkbox:checked'));
    if (selectedWorkers.length === 0) {
      showError('作業員を選択してください');
      return false;
    }

    if (!outputFormat) {
      showError('出力形式を選択してください');
      return false;
    }

    return true;
  }

  // 抽出条件取得
  function getExtractionConditions() {
    const startDate = container.querySelector('#start-date').value;
    const endDate = container.querySelector('#end-date').value;
    const selectedWorkers = Array.from(container.querySelectorAll('.worker-checkbox:checked')).map(cb => cb.value);
    const selectedItems = Array.from(container.querySelectorAll('.item-checkbox:checked')).map(cb => cb.value);
    const workLocation = container.querySelector('#work-location').value;
    const anomalyFilter = container.querySelector('#anomaly-filter').value;
    const interruptionFilter = container.querySelector('#interruption-filter').value;
    const outputFormat = container.querySelector('#output-format').value;

    return {
      startDate,
      endDate,
      selectedWorkers,
      selectedItems,
      workLocation,
      anomalyFilter,
      interruptionFilter,
      outputFormat
    };
  }

  // データフィルタリング
  function filterData(conditions) {
    let filteredRecords = workRecords.filter(record => {
      // 期間フィルタ
      const workDate = new Date(record.作業日);
      const start = new Date(conditions.startDate);
      const end = new Date(conditions.endDate);
      if (workDate < start || workDate > end) return false;

      // 作業員フィルタ
      if (conditions.selectedWorkers.length > 0 && !conditions.selectedWorkers.includes(record.作業員ID)) {
        return false;
      }

      // 作業場所フィルタ
      if (conditions.workLocation && record.作業場所 !== conditions.workLocation) {
        return false;
      }

      // 異常値フィルタ
      if (conditions.anomalyFilter === 'exclude') {
        const hasAnomaly = anomalyLogs.some(log => 
          log.検出対象レコードID === record.作業記録ID && log.検出対象テーブル === '作業記録'
        );
        if (hasAnomaly) return false;
      }

      return true;
    });

    // 中断記録フィルタ
    if (conditions.interruptionFilter === 'exclude') {
      const interruptedRecordIds = new Set(interruptionRecords.map(ir => ir.作業記録ID));
      filteredRecords = filteredRecords.filter(record => !interruptedRecordIds.has(record.作業記録ID));
    }

    return filteredRecords;
  }

  // プレビュー表示
  function showPreview() {
    if (!validateConditions()) return;

    const conditions = getExtractionConditions();
    const filteredData = filterData(conditions);

    const previewSection = container.querySelector('#preview-section');
    const previewContent = container.querySelector('#preview-content');
    const dataCount = container.querySelector('#data-count');

    // 条件文字列生成
    const workerNames = conditions.selectedWorkers.map(id => {
      const user = users.find(u => u.ユーザーID === id);
      return user ? user.氏名 || user.ユーザー名 : id;
    }).join(', ');

    const conditionText = `
      期間: ${conditions.startDate} ～ ${conditions.endDate}<br>
      作業員: ${workerNames || '全て'}<br>
      作業場所: ${conditions.workLocation || '全て'}<br>
      異常値データ: ${conditions.anomalyFilter === 'include' ? '含む' : '除外'}<br>
      中断記録: ${conditions.interruptionFilter === 'include' ? '含む' : '除外'}<br>
      出力形式: ${conditions.outputFormat.toUpperCase()}
    `;

    previewContent.innerHTML = conditionText;
    dataCount.textContent = `抽出対象データ件数: ${filteredData.length}件`;
    previewSection.style.display = 'block';
  }

  // CSV/Excel出力
  function exportData(conditions, data) {
    const headers = ['作業日', '作業員名', '作業開始時刻', '作業終了時刻', '作業時間', 'プロジェクト名', '作業場所', '作業種別', '作業内容', '進捗状況'];

    const rows = data.map(record => {
      const user = users.find(u => u.ユーザーID === record.作業員ID);
      return [
        record.作業日 || '',
        user ? (user.氏名 || user.ユーザー名) : '',
        record.作業開始時刻 || '',
        record.作業終了時刻 || '',
        record.作業時間 || '',
        record.プロジェクト名 || '',
        record.作業場所 || '',
        record.作業種別 || '',
        record.作業内容 || '',
        record.進捗状況 || ''
      ];
    });

    const csvContent = '\uFEFF' + [headers, ...rows].map(row => 
      row.map(cell => `"${String(cell).replace(/"/g, '""')}"`).join(',')
    ).join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    const url = URL.createObjectURL(blob);
    link.setAttribute('href', url);

    const timestamp = new Date().toISOString().slice(0, 19).replace(/[:-]/g, '');
    const extension = conditions.outputFormat === 'excel' ? 'csv' : 'csv'; // 簡易実装でCSVのみ
    link.setAttribute('download', `工数記録データ_${timestamp}.${extension}`);
    link.style.visibility = 'hidden';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  }

  // データ抽出実行
  async function executeExtraction() {
    if (!validateConditions()) return;

    const loadingEl = container.querySelector('#loading');
    loadingEl.style.display = 'block';

    try {
      // 最新データを取得
      const latestWorkRecords = await window.aivicApi.list(TABLE_WORK_RECORDS);
      if (latestWorkRecords) workRecords = latestWorkRecords;

      const conditions = getExtractionConditions();
      const filteredData = filterData(conditions);

      // 大量データのタイムアウトシミュレーション
      if (filteredData.length > 10000) {
        setTimeout(() => {
          loadingEl.style.display = 'none';
          showError('大量データ抽出処理がタイムアウトしました。条件を絞り込んでください。');
        }, 30000);
        return;
      }

      // 最大件数チェック
      const MAX_RECORDS = 50000;
      if (filteredData.length > MAX_RECORDS) {
        loadingEl.style.display = 'none';
        showError(`抽出件数が上限(${MAX_RECORDS}件)を超えています。条件を絞り込んでください。`);
        return;
      }

      setTimeout(() => {
        loadingEl.style.display = 'none';
        if (filteredData.length === 0) {
          showError('該当するデータが見つかりませんでした');
          return;
        }
        exportData(conditions, filteredData);
      }, 1000);

    } catch (error) {
      loadingEl.style.display = 'none';
      showError('データ抽出中にエラーが発生しました');
    }
  }

  // 条件クリア
  function clearConditions() {
    container.querySelector('#start-date').value = '';
    container.querySelector('#end-date').value = '';
    container.querySelector('#output-format').value = '';
    container.querySelector('#work-location').value = '';
    container.querySelector('#anomaly-filter').value = 'include';
    container.querySelector('#interruption-filter').value = 'exclude';

    container.querySelectorAll('.worker-checkbox').forEach(cb => cb.checked = false);
    container.querySelectorAll('.item-checkbox').forEach(cb => cb.checked = false);
    container.querySelector('#select-all-workers').checked = false;
    container.querySelector('#select-all-items').checked = false;

    container.querySelector('#preview-section').style.display = 'none';
  }

  // 条件保存
  function saveCondition() {
    const modal = container.querySelector('#condition-save-modal');
    modal.style.display = 'block';
  }

  // 初期描画
  renderWorkerList();
  renderWorkItemList();
  renderWorkLocations();

  // イベントリスナー
  container.querySelector('#select-all-workers').addEventListener('change', (e) => {
    container.querySelectorAll('.worker-checkbox').forEach(cb => cb.checked = e.target.checked);
  });

  container.querySelector('#select-all-items').addEventListener('change', (e) => {
    container.querySelectorAll('.item-checkbox').forEach(cb => cb.checked = e.target.checked);
  });

  container.querySelector('#btn-preview').addEventListener('click', showPreview);
  container.querySelector('#btn-extract').addEventListener('click', executeExtraction);
  container.querySelector('#btn-clear').addEventListener('click', clearConditions);
  container.querySelector('#btn-save-condition').addEventListener('click', saveCondition);
  container.querySelector('#btn-back').addEventListener('click', () => {
    window.showScreen("scr-1778907145716");
  });

  // モーダル関連
  container.querySelector('#btn-cancel-save').addEventListener('click', () => {
    container.querySelector('#condition-save-modal').style.display = 'none';
  });

  container.querySelector('#btn-confirm-save').addEventListener('click', () => {
    const conditionName = container.querySelector('#condition-name').value;
    if (!conditionName.trim()) {
      showError('条件名を入力してください');
      return;
    }

    // 条件保存処理（実装簡略化）
    container.querySelector('#condition-save-modal').style.display = 'none';
    container.querySelector('#condition-name').value = '';

    // 成功メッセージ表示
    const successEl = document.createElement('div');
    successEl.textContent = '条件が保存されました';
    successEl.style.cssText = 'position: fixed; top: 20px; right: 20px; background: rgba(34, 197, 94, 0.9); color: white; padding: 8px 16px; border-radius: 6px; font-size: 13px; z-index: 1001;';
    document.body.appendChild(successEl);
    setTimeout(() => document.body.removeChild(successEl), 3000);
  });

  // 今日の日付を初期値として設定
  const today = new Date().toISOString().split('T')[0];
  container.querySelector('#end-date').value = today;

  const monthAgo = new Date();
  monthAgo.setMonth(monthAgo.getMonth() - 1);
  container.querySelector('#start-date').value = monthAgo.toISOString().split('T')[0];
}

function(container, apiUrl, tables) {
  const tbody = container.querySelector("#record-tbody");
  const emptyMessage = container.querySelector("#empty-message");
  const detailModal = container.querySelector("#detail-modal");
  const detailContent = container.querySelector("#detail-content");

  // ユーザー情報をマップ化
  const userMap = {};
  if (tables[0]) {
    tables[0].records.forEach(user => {
      userMap[user.ユーザーID] = user.氏名;
    });
  }

  // 異常値検出関数
  function detectAnomalies(record) {
    const warnings = [];

    if (record.作業時間 && record.作業時間 > 1440) { // 24時間 = 1440分
      warnings.push("24時間を超える作業時間");
    }

    if (record.作業開始時刻 && record.作業終了時刻) {
      const start = new Date(record.作業開始時刻);
      const end = new Date(record.作業終了時刻);
      if (end <= start) {
        warnings.push("終了時刻が開始時刻より早い");
      }
    }

    return warnings;
  }

  // 時間フォーマット関数
  function formatTime(timestamp) {
    if (!timestamp) return "-";
    const date = new Date(timestamp);
    return date.toLocaleTimeString('ja-JP', { hour: '2-digit', minute: '2-digit' });
  }

  // 作業時間フォーマット関数
  function formatWorkTime(minutes) {
    if (!minutes) return "-";
    const hours = Math.floor(minutes / 60);
    const mins = minutes % 60;
    return `${hours}時間${mins}分`;
  }

  // 日付フォーマット関数
  function formatDate(timestamp) {
    if (!timestamp) return "-";
    const date = new Date(timestamp);
    return date.toLocaleDateString('ja-JP');
  }

  // 承認状態のスタイル
  function getStatusStyle(status) {
    switch (status) {
      case "承認済み":
        return "background: rgba(34, 197, 94, 0.1); color: #22c55e; padding: 2px 6px; border-radius: 4px; font-size: 11px;";
      case "未承認":
        return "background: rgba(251, 191, 36, 0.1); color: #fbbf24; padding: 2px 6px; border-radius: 4px; font-size: 11px;";
      case "差し戻し":
        return "background: rgba(239, 68, 68, 0.1); color: #ef4444; padding: 2px 6px; border-radius: 4px; font-size: 11px;";
      default:
        return "background: rgba(156, 163, 175, 0.1); color: #9ca3af; padding: 2px 6px; border-radius: 4px; font-size: 11px;";
    }
  }

  // テーブル再描画関数
  function renderRows(rows) {
    if (!rows || rows.length === 0) {
      tbody.innerHTML = "";
      emptyMessage.classList.remove("hidden");
      return;
    }

    emptyMessage.classList.add("hidden");

    tbody.innerHTML = rows.map(record => {
      const warnings = detectAnomalies(record);
      const warningIcon = warnings.length > 0 ? 
        `<span title="${warnings.join(', ')}" style="color: #ef4444; margin-left: 4px;">⚠️</span>` : "";

      const userName = userMap[record.作業員ID] || "不明";
      const canEdit = record.承認状態 !== "承認済み";
      const canApprove = record.承認状態 === "未承認";

      return `
        <tr data-id="${record.作業記録ID}" style="border-bottom: 1px solid rgba(255,255,255,0.05);">
          <td style="padding: 6px 10px; color: var(--text);">${formatDate(record.作業日)}</td>
          <td style="padding: 6px 10px; color: var(--text);">${userName}</td>
          <td style="padding: 6px 10px; color: var(--text);">${formatTime(record.作業開始時刻)}${warningIcon}</td>
          <td style="padding: 6px 10px; color: var(--text);">${formatTime(record.作業終了時刻)}</td>
          <td style="padding: 6px 10px; color: var(--text);">${formatWorkTime(record.作業時間)}</td>
          <td style="padding: 6px 10px; color: var(--text); max-width: 200px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;">${record.作業内容 || "-"}</td>
          <td style="padding: 6px 10px; color: var(--text);">${record.作業場所 || "-"}</td>
          <td style="padding: 6px 10px;">
            <span style="${getStatusStyle(record.承認状態)}">${record.承認状態}</span>
          </td>
          <td style="padding: 6px 10px;">
            <div style="display: flex; gap: 4px; flex-wrap: wrap;">
              <button class="detail-btn" data-id="${record.作業記録ID}" data-testid="detail-button" style="background: transparent; color: var(--text); border: 1px solid rgba(255,255,255,0.18); padding: 4px 8px; border-radius: 4px; font-size: 11px; cursor: pointer;">詳細</button>
              ${canEdit ? `<button class="edit-btn" data-id="${record.作業記録ID}" style="background: var(--primary); color: #fff; border: none; padding: 4px 8px; border-radius: 4px; font-size: 11px; cursor: pointer;">修正</button>` : ''}
              ${canApprove ? `<button class="approve-btn" data-id="${record.作業記録ID}" data-testid="approve-button" style="background: #22c55e; color: #fff; border: none; padding: 4px 8px; border-radius: 4px; font-size: 11px; cursor: pointer;">承認</button>` : ''}
              <button class="delete-btn" data-id="${record.作業記録ID}" data-testid="delete-button" style="background: #ef4444; color: #fff; border: none; padding: 4px 8px; border-radius: 4px; font-size: 11px; cursor: pointer;">削除</button>
            </div>
          </td>
        </tr>
      `;
    }).join("");
  }

  // 詳細表示関数
  function showDetail(recordId) {
    window.aivicApi.list(1).then(records => {
      const record = records.find(r => r.作業記録ID === recordId);
      if (!record) return;

      const userName = userMap[record.作業員ID] || "不明";
      const warnings = detectAnomalies(record);

      detailContent.innerHTML = `
        <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 16px;">
          <div>
            <h4 style="font-size: 13px; font-weight: 600; margin: 0 0 8px 0; color: var(--text);">基本情報</h4>
            <div style="background: rgba(255,255,255,0.02); padding: 12px; border-radius: 6px;">
              <div style="margin-bottom: 8px;">
                <span style="font-size: 11px; color: var(--text-muted);">作業日:</span>
                <span style="font-size: 13px; color: var(--text); margin-left: 8px;">${formatDate(record.作業日)}</span>
              </div>
              <div style="margin-bottom: 8px;">
                <span style="font-size: 11px; color: var(--text-muted);">作業者:</span>
                <span style="font-size: 13px; color: var(--text); margin-left: 8px;">${userName}</span>
              </div>
              <div style="margin-bottom: 8px;">
                <span style="font-size: 11px; color: var(--text-muted);">プロジェクト:</span>
                <span style="font-size: 13px; color: var(--text); margin-left: 8px;">${record.プロジェクト名 || "-"}</span>
              </div>
              <div>
                <span style="font-size: 11px; color: var(--text-muted);">作業場所:</span>
                <span style="font-size: 13px; color: var(--text); margin-left: 8px;">${record.作業場所 || "-"}</span>
              </div>
            </div>
          </div>

          <div>
            <h4 style="font-size: 13px; font-weight: 600; margin: 0 0 8px 0; color: var(--text);">時間情報</h4>
            <div style="background: rgba(255,255,255,0.02); padding: 12px; border-radius: 6px;">
              <div style="margin-bottom: 8px;">
                <span style="font-size: 11px; color: var(--text-muted);">開始時刻:</span>
                <span style="font-size: 13px; color: var(--text); margin-left: 8px;">${formatTime(record.作業開始時刻)}</span>
              </div>
              <div style="margin-bottom: 8px;">
                <span style="font-size: 11px; color: var(--text-muted);">終了時刻:</span>
                <span style="font-size: 13px; color: var(--text); margin-left: 8px;">${formatTime(record.作業終了時刻)}</span>
              </div>
              <div style="margin-bottom: 8px;">
                <span style="font-size: 11px; color: var(--text-muted);">実働時間:</span>
                <span style="font-size: 13px; color: var(--text); margin-left: 8px;">${formatWorkTime(record.作業時間)}</span>
              </div>
              <div>
                <span style="font-size: 11px; color: var(--text-muted);">承認状態:</span>
                <span style="${getStatusStyle(record.承認状態)}; margin-left: 8px;">${record.承認状態}</span>
              </div>
            </div>
          </div>
        </div>

        <div style="margin-top: 16px;">
          <h4 style="font-size: 13px; font-weight: 600; margin: 0 0 8px 0; color: var(--text);">作業内容詳細</h4>
          <div style="background: rgba(255,255,255,0.02); padding: 12px; border-radius: 6px;">
            <div style="margin-bottom: 8px;">
              <span style="font-size: 11px; color: var(--text-muted);">作業種別:</span>
              <span style="font-size: 13px; color: var(--text); margin-left: 8px;">${record.作業種別 || "-"}</span>
            </div>
            <div style="margin-bottom: 8px;">
              <span style="font-size: 11px; color: var(--text-muted);">作業内容:</span>
              <div style="font-size: 13px; color: var(--text); margin-top: 4px; white-space: pre-wrap;">${record.作業内容 || "-"}</div>
            </div>
            <div>
              <span style="font-size: 11px; color: var(--text-muted);">備考:</span>
              <div style="font-size: 13px; color: var(--text); margin-top: 4px; white-space: pre-wrap;">${record.備考 || "-"}</div>
            </div>
          </div>
        </div>

        ${warnings.length > 0 ? `
          <div style="margin-top: 16px;">
            <h4 style="font-size: 13px; font-weight: 600; margin: 0 0 8px 0; color: #ef4444;">⚠️ 異常値警告</h4>
            <div style="background: rgba(239, 68, 68, 0.1); border: 1px solid rgba(239, 68, 68, 0.3); padding: 12px; border-radius: 6px;">
              ${warnings.map(w => `<div style="font-size: 13px; color: #ef4444; margin-bottom: 4px;">• ${w}</div>`).join('')}
            </div>
          </div>
        ` : ''}
      `;

      detailModal.classList.remove("hidden");
    });
  }

  // CSVエクスポート関数
  function exportCSV() {
    window.aivicApi.list(1).then(records => {
      const headers = ["作業日", "作業者", "開始時刻", "終了時刻", "実働時間", "プロジェクト名", "作業場所", "作業種別", "作業内容", "承認状態", "備考"];
      const csvContent = [
        headers.join(","),
        ...records.map(record => {
          const userName = userMap[record.作業員ID] || "不明";
          return [
            `"${formatDate(record.作業日)}"`,
            `"${userName}"`,
            `"${formatTime(record.作業開始時刻)}"`,
            `"${formatTime(record.作業終了時刻)}"`,
            `"${formatWorkTime(record.作業時間)}"`,
            `"${record.プロジェクト名 || ""}"`,
            `"${record.作業場所 || ""}"`,
            `"${record.作業種別 || ""}"`,
            `"${(record.作業内容 || "").replace(/"/g, '""')}"`,
            `"${record.承認状態}"`,
            `"${(record.備考 || "").replace(/"/g, '""')}"`
          ].join(",");
        })
      ].join("\n");

      const blob = new Blob(["\uFEFF" + csvContent], { type: "text/csv;charset=utf-8;" });
      const link = document.createElement("a");
      link.href = URL.createObjectURL(blob);
      link.download = `工数記録_${new Date().toISOString().split('T')[0]}.csv`;
      link.click();
    });
  }

  // 初期データ描画
  renderRows(tables[1]?.records || []);

  // 検索ボタンイベント
  container.querySelector("#btn-search").addEventListener("click", () => {
    const selectedDate = container.querySelector("#input-date").value;
    const startDate = container.querySelector("#input-start-date").value;
    const endDate = container.querySelector("#input-end-date").value;

    // 日付範囲の妥当性チェック
    if (startDate && endDate && new Date(startDate) > new Date(endDate)) {
      alert("開始日は終了日より前の日付を指定してください");
      return;
    }

    window.aivicApi.list(1).then(records => {
      let filteredRecords = records;

      if (selectedDate) {
        filteredRecords = filteredRecords.filter(record => {
          const recordDate = new Date(record.作業日).toISOString().split('T')[0];
          return recordDate === selectedDate;
        });
      }

      if (startDate && endDate) {
        filteredRecords = filteredRecords.filter(record => {
          const recordDate = new Date(record.作業日).toISOString().split('T')[0];
          return recordDate >= startDate && recordDate <= endDate;
        });
      }

      renderRows(filteredRecords);
    });
  });

  // CSVエクスポートボタンイベント
  container.querySelector("#btn-export").addEventListener("click", exportCSV);

  // モーダル閉じるボタンイベント
  container.querySelector("#btn-close-modal").addEventListener("click", () => {
    detailModal.classList.add("hidden");
  });

  // イベントデリゲーション
  container.addEventListener("click", async (e) => {
    // 詳細表示
    const detailBtn = e.target.closest(".detail-btn");
    if (detailBtn) {
      showDetail(detailBtn.dataset.id);
      return;
    }

    // 修正ボタン
    const editBtn = e.target.closest(".edit-btn");
    if (editBtn) {
      window.showScreen("scr-1778907343735");
      return;
    }

    // 承認ボタン
    const approveBtn = e.target.closest(".approve-btn");
    if (approveBtn) {
      if (!confirm("この工数記録を承認しますか？")) return;

      const updated = await window.aivicApi.update(1, approveBtn.dataset.id, {
        承認状態: "承認済み",
        承認日時: new Date().toISOString()
      });

      if (updated) {
        const records = await window.aivicApi.list(1);
        renderRows(records);
      }
      return;
    }

    // 削除ボタン
    const deleteBtn = e.target.closest(".delete-btn");
    if (deleteBtn) {
      if (!confirm("この工数記録を削除しますか？")) return;

      await window.aivicApi.delete(1, deleteBtn.dataset.id);
      const records = await window.aivicApi.list(1);
      renderRows(records);
      return;
    }
  });

  // モーダル背景クリックで閉じる
  detailModal.addEventListener("click", (e) => {
    if (e.target === detailModal) {
      detailModal.classList.add("hidden");
    }
  });
}

function(container, apiUrl, tables) {
  // 現在のユーザー情報を設定
  const currentUser = { id: 'user-001', name: '田中太郎' };
  container.querySelector('#worker-name').value = currentUser.name;

  // 今日の日付を設定
  const today = new Date().toISOString().split('T')[0];
  container.querySelector('#work-date').value = today;
  container.querySelector('#work-date').max = today; // 未来日付を制限

  // 作業項目マスタの読み込み
  async function loadWorkItems() {
    const workItemSelect = container.querySelector('#work-item');
    const workItems = await window.aivicApi.list(3) || []; // 作業項目マスタ
    workItemSelect.innerHTML = '<option value="">選択してください</option>';
    workItems.forEach(item => {
      const option = document.createElement('option');
      option.value = item.作業項目名;
      option.textContent = `${item.作業項目コード} - ${item.作業項目名}`;
      workItemSelect.appendChild(option);
    });
  }

  // 文字数カウンター
  const workContentTextarea = container.querySelector('#work-content');
  const charCountSpan = container.querySelector('#char-count');
  workContentTextarea.addEventListener('input', () => {
    charCountSpan.textContent = workContentTextarea.value.length;
  });

  // 工数計算機能
  function calculateWorkHours() {
    const startTime = container.querySelector('#start-time').value;
    const endTime = container.querySelector('#end-time').value;
    const breakTime = parseInt(container.querySelector('#break-time').value) || 0;

    if (!startTime || !endTime) {
      container.querySelector('#calculated-hours').textContent = '0.0h';
      return 0;
    }

    const start = new Date(`2000-01-01T${startTime}`);
    const end = new Date(`2000-01-01T${endTime}`);

    if (end <= start) {
      showError(['開始時刻が終了時刻より後になっています']);
      container.querySelector('#calculated-hours').textContent = '0.0h';
      return 0;
    }

    const totalMinutes = (end - start) / (1000 * 60);
    const workMinutes = totalMinutes - breakTime;

    if (workMinutes < 0) {
      showError(['中断時間は作業時間を超過できません']);
      container.querySelector('#calculated-hours').textContent = '0.0h';
      return 0;
    }

    if (totalMinutes >= 24 * 60) {
      showError(['24時間以上の作業時間は入力できません']);
      container.querySelector('#calculated-hours').textContent = '0.0h';
      return 0;
    }

    const hours = (workMinutes / 60).toFixed(1);
    container.querySelector('#calculated-hours').textContent = `${hours}h`;
    return workMinutes;
  }

  // エラー表示機能
  function showError(messages) {
    const errorSection = container.querySelector('#error-messages');
    const errorList = container.querySelector('#error-list');
    errorList.innerHTML = messages.map(msg => `<div>• ${msg}</div>`).join('');
    errorSection.style.display = 'block';
  }

  function hideError() {
    container.querySelector('#error-messages').style.display = 'none';
  }

  // バリデーション機能
  function validateForm() {
    const errors = [];
    const workDate = container.querySelector('#work-date').value;
    const projectName = container.querySelector('#project-name').value.trim();
    const workLocation = container.querySelector('#work-location').value;
    const workItem = container.querySelector('#work-item').value;
    const workType = container.querySelector('#work-type').value;
    const startTime = container.querySelector('#start-time').value;
    const endTime = container.querySelector('#end-time').value;
    const workContent = container.querySelector('#work-content').value.trim();

    if (!workDate) errors.push('作業日付は必須です');
    if (!projectName) errors.push('プロジェクト名は必須です');
    if (!workLocation) errors.push('作業場所は必須です');
    if (!workItem) errors.push('作業項目は必須です');
    if (!workType) errors.push('作業種別は必須です');
    if (!startTime) errors.push('開始時刻は必須です');
    if (!endTime) errors.push('終了時刻は必須です');
    if (!workContent) errors.push('作業内容詳細は必須です');

    // 未来日付チェック
    if (workDate && new Date(workDate) > new Date(today)) {
      errors.push('未来日付は選択できません');
    }

    // 文字数制限チェック
    if (workContent.length > 1000) {
      errors.push('作業内容詳細は1000文字以内で入力してください');
    }

    return errors;
  }

  // フォームクリア機能
  function clearForm() {
    container.querySelector('#work-date').value = today;
    container.querySelector('#project-name').value = '';
    container.querySelector('#work-location').value = '';
    container.querySelector('#work-item').value = '';
    container.querySelector('#work-type').value = '';
    container.querySelector('#start-time').value = '';
    container.querySelector('#end-time').value = '';
    container.querySelector('#break-time').value = '';
    container.querySelector('#work-content').value = '';
    container.querySelector('#remarks').value = '';
    container.querySelector('#calculated-hours').textContent = '0.0h';
    container.querySelector('#char-count').textContent = '0';
    hideError();
  }

  // イベントリスナー設定

  // 時刻変更時の自動計算
  container.querySelector('#start-time').addEventListener('change', calculateWorkHours);
  container.querySelector('#end-time').addEventListener('change', calculateWorkHours);
  container.querySelector('#break-time').addEventListener('input', calculateWorkHours);

  // 再計算ボタン
  container.querySelector('#btn-calculate').addEventListener('click', calculateWorkHours);

  // 中断時間追加ボタン
  container.querySelector('#btn-add-break').addEventListener('click', () => {
    window.showScreen('scr-1778907238439'); // 中断記録入力画面
  });

  // 一時保存ボタン
  container.querySelector('#btn-temp-save').addEventListener('click', async () => {
    hideError();
    const errors = validateForm();
    if (errors.length > 0) {
      showError(errors);
      return;
    }

    const workMinutes = calculateWorkHours();
    if (workMinutes === 0 && container.querySelector('#start-time').value && container.querySelector('#end-time').value) {
      return; // エラーが既に表示されている
    }

    const workRecord = {
      作業員ID: currentUser.id,
      作業日: new Date(container.querySelector('#work-date').value).toISOString(),
      作業開始時刻: new Date(`${container.querySelector('#work-date').value}T${container.querySelector('#start-time').value}`).toISOString(),
      作業終了時刻: container.querySelector('#end-time').value ? new Date(`${container.querySelector('#work-date').value}T${container.querySelector('#end-time').value}`).toISOString() : null,
      作業時間: workMinutes,
      プロジェクト名: container.querySelector('#project-name').value.trim(),
      作業場所: container.querySelector('#work-location').value,
      作業種別: container.querySelector('#work-type').value,
      作業内容: container.querySelector('#work-content').value.trim(),
      進捗状況: '一時保存',
      備考: container.querySelector('#remarks').value.trim(),
      承認状態: '未承認',
      作成者ID: currentUser.id
    };

    const saved = await window.aivicApi.save(1, workRecord); // 作業記録テーブル
    if (saved) {
      alert('一時保存が完了しました');
    }
  });

  // 記録確定ボタン
  container.querySelector('#btn-save').addEventListener('click', async () => {
    hideError();
    const errors = validateForm();
    if (errors.length > 0) {
      showError(errors);
      return;
    }

    const workMinutes = calculateWorkHours();
    if (workMinutes === 0 && container.querySelector('#start-time').value && container.querySelector('#end-time').value) {
      return; // エラーが既に表示されている
    }

    if (!confirm('工数記録を確定しますか？確定後は修正できません。')) {
      return;
    }

    const workRecord = {
      作業員ID: currentUser.id,
      作業日: new Date(container.querySelector('#work-date').value).toISOString(),
      作業開始時刻: new Date(`${container.querySelector('#work-date').value}T${container.querySelector('#start-time').value}`).toISOString(),
      作業終了時刻: new Date(`${container.querySelector('#work-date').value}T${container.querySelector('#end-time').value}`).toISOString(),
      作業時間: workMinutes,
      プロジェクト名: container.querySelector('#project-name').value.trim(),
      作業場所: container.querySelector('#work-location').value,
      作業種別: container.querySelector('#work-type').value,
      作業内容: container.querySelector('#work-content').value.trim(),
      進捗状況: '完了',
      備考: container.querySelector('#remarks').value.trim(),
      承認状態: '未承認',
      作成者ID: currentUser.id
    };

    const saved = await window.aivicApi.save(1, workRecord); // 作業記録テーブル
    if (saved) {
      alert('工数記録が正常に登録されました');
      clearForm();
      window.showScreen('scr-1778907145716'); // 作業履歴一覧画面
    }
  });

  // キャンセルボタン
  container.querySelector('#btn-cancel').addEventListener('click', () => {
    if (confirm('入力内容をクリアしますか？')) {
      clearForm();
    }
  });

  // ナビゲーションボタン
  container.querySelector('#btn-history').addEventListener('click', () => {
    window.showScreen('scr-1778907145716'); // 作業履歴一覧画面
  });

  container.querySelector('#btn-break-record').addEventListener('click', () => {
    window.showScreen('scr-1778907238439'); // 中断記録入力画面
  });

  // 初期化処理
  loadWorkItems();
}
